package main
import ("os"; "fmt"; "image"; _ "image/png"; _ "image/jpeg"; _ "image/gif")
func main(){
 for _,p:=range os.Args[1:]{
   f,_:=os.Open(p); img,format,err:=image.Decode(f); f.Close()
   if err!=nil {fmt.Println(p,err); continue}
   b:=img.Bounds(); fmt.Printf("%s %s %v first few:",p,format,b)
   for y:=b.Min.Y; y<b.Min.Y+2 && y<b.Max.Y; y++ { for x:=b.Min.X; x<b.Min.X+4 && x<b.Max.X; x++ { r,g,bl,a:=img.At(x,y).RGBA(); fmt.Printf(" (%d,%d,%d,%d)",r>>8,g>>8,bl>>8,a>>8)}}
   fmt.Println()
 }
}
EOF
