import subprocess, sys, re, concurrent.futures, os, json, zlib, struct
sys.path.insert(0,'/tmp')
from mkpng import png as writepng
# generate png bytes in memory using same logic by writing to BytesIO? mkpng writes path only; duplicate function
def pngbytes(pixels,w,h):
    raw=b''
    for row in pixels: raw+=b'\x00'+b''.join(bytes(p) for p in row)
    def chunk(t,data):
        return struct.pack(">I",len(data))+t+data+struct.pack(">I",zlib.crc32(t+data)&0xffffffff)
    ct=6 if len(pixels[0][0])==4 else 2
    return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack(">IIBBBBB",w,h,8,ct,0,0,0))+chunk(b'IDAT',zlib.compress(raw))+chunk(b'IEND',b'')
def run_one(task):
    cp,x,y=task
    pix=[[(255,255,255) if (xx==x and yy==y) else (0,0,0) for xx in range(8)] for yy in range(8)]
    inp=pngbytes(pix,8,8)
    env={"PATH":os.environ.get("PATH",""),"LC_ALL":"C.UTF-8"}
    p=subprocess.run(["./executable","--probe=off","-f","symbols","-c","full","-s","1x1","-p","off",f"--symbols=U+{cp:04X}","-"],input=inp,capture_output=True,env=env,timeout=5)
    out=p.stdout
    fg=re.search(br'38;2;(\d+);(\d+);(\d+)',out)
    bg=re.search(br'48;2;(\d+);(\d+);(\d+)',out)
    f=int(fg.group(1)) if fg else 0
    b=int(bg.group(1)) if bg else 0
    inv=b'\x1b[7m' in out
    # strip ansi to get glyph char
    txt=re.sub(br'\x1b\[[0-9;]*m',b'',out).decode('utf-8','replace').strip('\n')
    return (cp,x,y,f,b,inv,txt)
def extract(cps):
    tasks=[(cp,x,y) for cp in cps for y in range(8) for x in range(8)]
    results={}
    with concurrent.futures.ThreadPoolExecutor(max_workers=24) as ex:
        for cp,x,y,f,b,inv,txt in ex.map(run_one,tasks):
            d=results.setdefault(cp,{"bits":0,"txt":txt,"inv":inv})
            if f>0 and b==0:
                # if inverted, this is space-like: do not set? Mark special later based txt
                d["bits"] |= (1 << (y*8+x))
            elif b>0 and f==0:
                pass
            elif f>0 and b>0:
                d.setdefault("both",[]).append((x,y,f,b))
            else:
                d.setdefault("none",[]).append((x,y))
    return results
cps=list(range(32,127))
res=extract(cps)
