var progName string

func fatalParse(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "%s: %s\n", progName, fmt.Sprintf(format, args...))
	os.Exit(2)
}

func localeIsUTF8() bool {
	for _, k := range []string{"LC_ALL", "LC_CTYPE", "LANG"} {
		v := os.Getenv(k)
		if v != "" {
			lv := strings.ToLower(v)
			return strings.Contains(lv, "utf-8") || strings.Contains(lv, "utf8")
		}
	}
	return false
}

func checkArgConversion(s string) {
	// GLib converts string/callback option arguments according to locale.
	needs := false
	for i := 0; i < len(s); i++ { if s[i] >= 0x80 { needs = true; break } }
	if !needs { return }
	if localeIsUTF8() {
		if !utf8.ValidString(s) { fatalParse("Invalid byte sequence in conversion input") }
		// Locales named *.UTF-8 other than C.UTF-8 may not be installed in
		// this environment; glibc would fall back to C. Recognise the two
		// UTF-8 locales that are available on the reference system.
		ok := false
		for _, k := range []string{"LC_ALL", "LC_CTYPE", "LANG"} {
			v := os.Getenv(k)
			if v != "" {
				lv := strings.ToLower(v)
				if lv == "c.utf-8" || lv == "c.utf8" { ok = true }
				break
			}
		}
		if !ok { fatalParse("Invalid byte sequence in conversion input") }
		return
	}
	fatalParse("Invalid byte sequence in conversion input")
}

func parseBool(s string) (bool, bool) {
	switch strings.ToLower(s) {
	case "on", "yes", "true": return true, true
	case "off", "no", "false": return false, true
	}
	return false, false
}
func parseTri(s string) (TriState, bool) {
	if strings.EqualFold(s, "auto") { return TriAuto, true }
	if b, ok := parseBool(s); ok { if b { return TriOn, true }; return TriOff, true }
	return TriAuto, false
}

// ---- C strtod helpers ----
func isSpaceByte(b byte) bool { return b==' '||b=='\t'||b=='\n'||b=='\v'||b=='\f'||b=='\r' }

// parseCDoublePrefix parses a C strtod at start (after optional spaces), returning value and bytes consumed (including leading spaces).
func parseCDoublePrefix(s string) (float64, int, bool) {
	i := 0
	for i < len(s) && isSpaceByte(s[i]) { i++ }
	start := i
	// inf/nan
	rest := strings.ToLower(s[i:])
	sign := 1.0
	j := i
	if j < len(s) && (s[j]=='+' || s[j]=='-') { if s[j]=='-' { sign=-1 }; j++ }
	low := strings.ToLower(s[j:])
	if strings.HasPrefix(low, "infinity") { return sign*math.Inf(1), j+8, true }
	if strings.HasPrefix(low, "inf") { return sign*math.Inf(1), j+3, true }
	if strings.HasPrefix(low, "nan") {
		end := j+3
		// nan(n-char-seq)
		if end < len(s) && s[end]=='(' {
			k := end+1
			for k < len(s) && (isAlphaNumByte(s[k]) || s[k]=='_') { k++ }
			if k < len(s) && s[k]==')' { end = k+1 }
		}
		return math.NaN(), end, true
	}
	_ = rest; _ = start
	// scan a valid decimal or hex number at j
	end := scanNumber(s, j)
	if end == j { return 0, 0, false }
	txt := s[j:end]
	v := evalNumber(txt)
	return sign*v, end, true
}
func isAlphaNumByte(b byte) bool { return (b>='0'&&b<='9')||(b>='a'&&b<='z')||(b>='A'&&b<='Z') }
func isDigit(b byte) bool { return b>='0'&&b<='9' }
func isHexDigit(b byte) bool { return isDigit(b)||(b>='a'&&b<='f')||(b>='A'&&b<='F') }
func scanNumber(s string, i int) int {
	n := len(s)
	// hex
	if i+1 < n && s[i]=='0' && (s[i+1]=='x' || s[i+1]=='X') {
		j := i+2; digits := 0
		for j < n && isHexDigit(s[j]) { j++; digits++ }
		if j < n && s[j]=='.' { j++; for j < n && isHexDigit(s[j]) { j++; digits++ } }
		if digits==0 { return i }
		if j < n && (s[j]=='p' || s[j]=='P') {
			k := j+1
			if k < n && (s[k]=='+'||s[k]=='-') { k++ }
			d := 0; for k < n && isDigit(s[k]) { k++; d++ }
			if d>0 { j = k } // strtod requires p exponent for hex in C? it accepts without? C99 hex float requires p, but integer 0x10 parses as 0 then? Our callers saw 0x10 accepted as 16. Keep j without exponent.
		}
		return j
	}
	j := i; digits:=0
	for j < n && isDigit(s[j]) { j++; digits++ }
	if j < n && s[j]=='.' { j++; for j < n && isDigit(s[j]) { j++; digits++ } }
	if digits==0 { return i }
