func hexVal(b byte) int { if b<='9' { return int(b-'0') }; if b<='F' { return int(b-'A')+10 }; return int(b-'a')+10 }

// ---- size parsing ----
func strtolDecimalPrefix(s string) (int64, int, bool) {
	i:=0
	for i<len(s) && isSpaceByte(s[i]) { i++ }
	startSign:=i
	if i<len(s) && (s[i]=='+'||s[i]=='-') { i++ }
	digitsStart:=i
	var val uint64; overflow:=false
	for i<len(s) && isDigit(s[i]) {
		d:=uint64(s[i]-'0')
		if val > (math.MaxUint64-d)/10 { overflow=true } else { val=val*10+d }
		i++
	}
	if i==digitsStart { return 0,0,false }
	neg := startSign<len(s) && s[startSign]=='-'
	var sv int64
	if overflow { if neg { sv=math.MinInt64 } else { sv=math.MaxInt64 } } else if neg {
		if val==9223372036854775808 { sv=math.MinInt64 } else if val>9223372036854775808 { sv=math.MinInt64 } else { sv=-int64(val) }
	} else {
		if val>math.MaxInt64 { sv=math.MaxInt64 } else { sv=int64(val) }
	}
	return sv,i,true
}
func cast32(v int64) int { return int(int32(v)) }

// returns w,h,syntaxErr. w/h=-1 unspecified.
func parseSizeRaw(s string) (int,int,bool) {
	w64, end, ok := strtolDecimalPrefix(s)
