	}
	return w,h,false
}
func parseSize(s string, kind string) (int,int) {
	w,h,syn := parseSizeRaw(s)
	if syn {
		switch kind {
		case "size": fatalParse("Size must be specified as [width]x[height], [width]x or x[height], e.g 80x25, 80x or x25.")
		case "view": fatalParse("View size must be specified as [width]x[height], [width]x or x[height], e.g 80x25, 80x or x25.")
		case "grid": fatalParse("Grid size must be specified as [width]x[height], [width]x or x[height], e.g 4x4, 4x or x4.")
		}
	}
	if w==0 || h==0 {
