func applyAlign(o *Options, v string) {
	if v=="" { return }
	parts := strings.Split(v, ",")
	// Local assignments for this option invocation.
	var haveH, haveV bool
	var newH, newV int
	var amb []bool // presence list
	for idx, p := range parts {
		if idx>=2 { fatalParse("Too many alignment specifiers in \"%s\". Must be at most two.", v) }
		switch strings.ToLower(p) {
		case "left": newH=-1; haveH=true
		case "right": newH=1; haveH=true
		case "top": newV=-1; haveV=true
		case "bottom": newV=1; haveV=true
		case "mid","center": amb=append(amb,true)
		default: fatalParse("Unknown alignment specifier \"%s\".", p)
		}
	}
	// Assign ambiguous specifiers to axes not explicitly given, horizontal first.
	ambH:=false; ambV:=false
	for range amb {
		if !haveH && !ambH { ambH=true } else if !haveV && !ambV { ambV=true } else if !ambH { ambH=true } else if !ambV { ambV=true }
	}
	if haveH { o.AlignH=newH } else if ambH { o.AlignH=0 }
	if haveV { o.AlignV=newV } else if ambV { o.AlignV=0 }
}

func applySpeed(o *Options, v string) {
	msg := "Animation speed must be either \"max\", a real multiplier, or a real framerate followed by \"fps\". It must be greater than zero."
	lv := strings.ToLower(v)
	if strings.HasPrefix(lv, "max") {
		// The original recognises any string beginning with "max" here.
		o.SpeedMax=true; o.SpeedSet=true; o.SpeedFPS=false; o.Speed=math.Inf(1); return
	}
	if strings.HasSuffix(lv, "fps") {
		num := v[:len(v)-3]
		val, ok := parseCDoubleFull(num)
		if !ok || !(val>0) { fatalParse("%s",msg) }
		o.Speed=val; o.SpeedFPS=true; o.SpeedMax=false; o.SpeedSet=true; return
	}
	val, ok := parseCDoubleFull(v)
	if !ok || !(val>0) { fatalParse("%s",msg) }
	o.Speed=val; o.SpeedFPS=false; o.SpeedMax=false; o.SpeedSet=true
}

func parseArgs(args []string) *Options {
	o := defaultOptions()
	defs := buildOptDefs()
	byLong := map[string]*optDef{}
	byShort := map[byte]*optDef{}
	for _, d := range defs {
		if d.long!="" { byLong[d.long]=d }
		if d.short!=0 { byShort[d.short]=d }
	}
	remaining := false
	for i:=0;i<len(args);i++ {
		a := args[i]
		if remaining {
			o.Positionals=append(o.Positionals,a); continue
		}
		if a=="--" {
			remaining=true
			// GLib leaves a "--" placeholder in the remaining arguments when
			// any following argument begins with '-'.
			hasDash:=false
			for _, r := range args[i+1:] { if len(r)>0 && r[0]=='-' { hasDash=true; break } }
			if hasDash { o.Positionals=append(o.Positionals,"--") }
			continue
		}
		if len(a)>=2 && a[0]=='-' && a[1]=='-' {
			// long
			body:=a[2:]
			name:=body; val:=""; hasEq:=false
			if eq:=strings.IndexByte(body,'='); eq>=0 { name=body[:eq]; val=body[eq+1:]; hasEq=true }
			d, ok := byLong[name]
			if !ok { fatalParse("Unknown option %s", a) }
			optName:="--"+name
			if d.kind==argNone {
				d.apply(o,"",optName)
			} else {
				var v string
				if hasEq { v=val } else {
					if i+1>=len(args) { fatalParse("Missing argument for %s", optName) }
					i++; v=args[i]
				}
				if d.kind!=argFilename { /* conversion check done in callback/int parse below */ if d.kind!=argInt { /* callback handles */ } }
				if d.kind==argInt { checkArgConversion(v) }
				d.apply(o,v,optName)
			}
			continue
		}
		if len(a)>=2 && a[0]=='-' && a!="-" {
			// short group
			consumedArg:=false
			for idx:=1; idx<len(a); idx++ {
				ch:=a[idx]
				d, ok := byShort[ch]
				if !ok { fatalParse("Unknown option %s", a) }
				optName:="-"+string(ch)
				if d.kind==argNone {
					d.apply(o,"",optName)
					continue
				}
				// arg-taking: rest of token ignored, next argv is value
				if i+1>=len(args) { fatalParse("Missing argument for %s", optName) }
				i++; v:=args[i]
				if d.kind==argInt { checkArgConversion(v) }
				d.apply(o,v,optName)
				consumedArg=true
				break
			}
			_ = consumedArg
			continue
		}
		o.Positionals=append(o.Positionals,a)
	}
	return o
}

var _ = os.Stderr
EOF"}

