		case "left": newH=-1; haveH=true
		case "right": newH=1; haveH=true
		case "top": newV=-1; haveV=true
		case "bottom": newV=1; haveV=true
		case "mid","center": amb=append(amb,true)
		default: fatalParse("Unknown alignment specifier \"%s\".", p)
		}
	}
	// Assign ambiguous specifiers to axes not explicitly given, horizontal first.
	ambH:=false; ambV:=false
	for range amb {
		if !haveH && !ambH { ambH=true } else if !haveV && !ambV { ambV=true } else if !ambH { ambH=true } else if !ambV { ambV=true }
	}
