var knownTags = []string{
	"all","alnum","alpha","ambiguous","ascii","bad","block","border","braille","diagonal","digit","dot","extra","geometric","half","hhalf","imported","inverted","latin","legacy","narrow","none","quad","sextant","solid","space","stipple","technical","ugly","vhalf","wedge","wide",
}

func lookupTag(tok string) (string,bool) {
	lt:=strings.ToLower(tok)
	for _, t := range knownTags { if t==lt { return t,true } }
	// The original appears to accept unambiguous (and some ambiguous) prefixes.
	for _, t := range knownTags { if strings.HasPrefix(t,lt) { return t,true } }
	return "",false
}

type selTerm struct {
	Explicit bool
	Remove bool
	Tag string // either tag (resolved)
	CPs []rune // or codepoints/ranges (HasCPs distinguishes empty set)
	HasCPs bool
}

func parseSelector(s string) []selTerm {
	// Returns terms; calls fatalParse on error with original messages.
	var terms []selTerm
	i:=0
	explicit:=false; remove:=false; haveOp:=false
	for i<len(s) {
		c:=s[i]
		if c==' '||c=='\t'||c==',' { i++; continue }
		if c=='+' || c=='-' {
			if haveOp { fatalParse("Syntax error in symbol tag selectors.") }
			explicit=true; remove=(c=='-'); haveOp=true; i++; continue
		}
		// a term starts here
		term:=selTerm{Explicit:explicit,Remove:remove}
		if c=='[' {
			// parse set
			cps, consumed := parseBracketSet(s[i:])
			term.CPs=cps; term.HasCPs=true; i+=consumed
		} else if isCodepointStart(s[i:]) {
			cps, consumed := parseCodepointTerm(s[i:])
			term.CPs=cps; term.HasCPs=true; i+=consumed
		} else if isASCIILetter(c) || isDigit(c) {
			start:=i
			for i<len(s) && (isASCIILetter(s[i]) || isDigit(s[i])) { i++ }
			tok:=s[start:i]
			// Check range form for bare hex hthat starts with a digit and is followed by -codepoint
			// Bare hex was handled in isCodepointStart (digit start), so this is a tag or invalid hex token.
			tag, ok := lookupTag(tok)
			if !ok { fatalParse("Unrecognized symbol tag '%s'.", tok) }
			term.Tag=tag
		} else {
			fatalParse("Syntax error in symbol tag selectors.")
		}
		terms=append(terms,term)
		explicit=false; remove=false; haveOp=false
	}
	return terms
}

func isASCIILetter(b byte)bool{return (b>='a'&&b<='z')||(b>='A'&&b<='Z')}

func parseBracketSet(s string) ([]rune,int) {
	// s starts with '['. Find unescaped ']'.
	i:=1; var raw []rune; var escaped []bool
	for i<len(s) {
		if s[i]=='\\' && i+1<len(s) {
			r, sz := utf8.DecodeRuneInString(s[i+1:])
			if r==utf8.RuneError && sz==0 { r='?'; sz=1 }
			raw=append(raw,r); escaped=append(escaped,true); i+=1+sz; continue
		}
		if s[i]==']' {
			// interpret ranges
			var cps []rune
			for k:=0;k<len(raw);k++ {
				if k+2<len(raw) && raw[k+1]=='-' && !escaped[k+1] {
					a,b:=raw[k],raw[k+2]
					if a>b { a,b=b,a }
					// Cap ranges to Unicode range to avoid absurd ranges like 0..0x10FFFF creating huge slice; original likewise builds a bitset. Cap at 0x2FFFF.
					if b>0x2FFFF { b=0x2FFFF }
					for cp:=a; cp<=b; cp++ { cps=append(cps,cp) }
					k+=2
				} else {
					cps=append(cps,raw[k])
				}
			}
			return cps, i+1
		}
		r, sz := utf8.DecodeRuneInString(s[i:])
		if r==utf8.RuneError && sz==0 { r=rune(s[i]); sz=1 }
		raw=append(raw,r); escaped=append(escaped,false); i+=sz
	}
	fatalParse("Syntax error in symbol selector set.")
	return nil,0
}

func scanCodepoint(s string) (rune,int,bool) {
	// U+hex, 0xhex, or bare hex starting with digit
	if len(s)>=2 && (s[0]=='U'||s[0]=='u') && s[1]=='+' {
		j:=2; start:=j
		for j<len(s)&&isHexDigit(s[j]) { j++ }
		if j==start { return 0,0,false }
		v:=0
		for _,c := range s[start:j] { v=v*16+hexVal(byte(c)); if v>0x2FFFF { /* keep huge but cap for return */ } }
		return rune(v),j,true
	}
	if len(s)>=2 && s[0]=='0' && (s[1]=='x'||s[1]=='X') {
		j:=2; start:=j
		for j<len(s)&&isHexDigit(s[j]) { j++ }
		if j==start { return 0,0,false }
		v:=0; for _,c := range s[start:j] { v=v*16+hexVal(byte(c)) }
		return rune(v),j,true
	}
	if len(s)>=1 && isDigit(s[0]) {
		// bare hex token must be all hex digits and not followed by a non-hex letter.
		j:=0; for j<len(s)&&isHexDigit(s[j]) { j++ }
		if j<len(s) && isASCIILetter(s[j]) { return 0,0,false }
		if j==0 { return 0,0,false }
		v:=0; for _,c := range s[:j] { v=v*16+hexVal(byte(c)) }
		return rune(v),j,true
	}
	return 0,0,false
}

func isCodepointStart(s string) bool {
	_,_,ok:=scanCodepoint(s); return ok
}

func parseCodepointTerm(s string) ([]rune,int) {
	cp, n, ok := scanCodepoint(s)
	if !ok { fatalParse("Syntax error in symbol tag selectors.") }
	// Look for a range: '-' followed by another codepoint which is followed by a delimiter or end.
	if n < len(s) && s[n]=='-' {
		if cp2, n2, ok2 := scanCodepoint(s[n+1:]); ok2 {
			after:=n+1+n2
			if after==len(s) || s[after]=='+'||s[after]=='-'||s[after]==','||s[after]==' '||s[after]=='\t'||s[after]=='[' {
				a,b:=cp,cp2; if a>b { a,b=b,a }
				if b>0x2FFFF { b=0x2FFFF }
				var cps []rune
				for c:=a;c<=b;c++ { cps=append(cps,c) }
				return cps, after
			}
		}
	}
	return []rune{cp}, n
}

func validateSymbolSelector(s string) {
	_ = parseSelector(s)
}

// SymbolSet is a set of codepoints present in the inventory.
type SymbolSet struct { Present map[rune]bool }
func newSymbolSet() *SymbolSet { return &SymbolSet{Present: map[rune]bool{}} }
func (s *SymbolSet) clear(){ s.Present=map[rune]bool{} }
func (s *SymbolSet) addCP(cp rune){ if _,ok:=glyphByCP[cp]; ok { s.Present[cp]=true } }
func (s *SymbolSet) removeCP(cp rune){ delete(s.Present,cp) }
func (s *SymbolSet) addTag(tag string){
	if tag=="none" { return }
	for _, g := range allGlyphs { if tag=="all" || g.Tags[tag] { s.Present[g.CP]=true } }
}
func (s *SymbolSet) removeTag(tag string){
	if tag=="none" { return }
	if tag=="all" { s.clear(); return }
	for _, g := range allGlyphs { if g.Tags[tag] { delete(s.Present,g.CP) } }
}

func (s *SymbolSet) applySelectors(strs []string) {
	for _, str := range strs {
		terms:=parseSelector(str)
		for ti, term := range terms {
			remove:=term.Remove
			if ti==0 && !term.Explicit {
				s.clear()
			}
			if term.HasCPs {
				for _, cp := range term.CPs { if remove { s.removeCP(cp) } else { s.addCP(cp) } }
			} else if term.Tag!="" {
				if remove { s.removeTag(term.Tag) } else { s.addTag(term.Tag) }
			}
		}
	}
	// Space is always available as a fallback in the original canvas.
	s.Present[' ']=true
}

func (s *SymbolSet) glyphs() []*Glyph {
	var out []*Glyph
	for _, g := range allGlyphs { if s.Present[g.CP] { out=append(out,g) } }
	return out
}

var importedGlyphs []*Glyph
func loadGlyphFile(path string) bool {
	data, err := readFileBytes(path)
	if err!=nil || len(data)<4 { return false }
	// Common font signatures recognised by FreeType.
	sig := string(data[:4])
	switch sig {
	case "\x00\x01\x00\x00","OTTO","true","typ1","ttcf","wOFF","wOF2","\x01fcp":
		return true
	}
	if strings.HasPrefix(string(data), "STARTFONT") { return true }
	// PCF files start with \x01 'f' 'c' 'p'; BDF handled above.
	return false
}
