func loadGlyphFile(path string) bool {
	data, err := readFileBytes(path)
	if err!=nil || len(data)<4 { return false }
	// Common font signatures recognised by FreeType.
	sig := string(data[:4])
	switch sig {
	case "\x00\x01\x00\x00","OTTO","true","typ1","ttcf","wOFF","wOF2","\x01fcp":
		return true
	}
	if strings.HasPrefix(string(data), "STARTFONT") { return true }
	// PCF files start with \x01 'f' 'c' 'p'; BDF handled above.
	return false
}
