func lookupTag(tok string) (string,bool) {
	lt:=strings.ToLower(tok)
	for _, t := range knownTags { if t==lt { return t,true } }
	// The original appears to accept unambiguous (and some ambiguous) prefixes.
	for _, t := range knownTags { if strings.HasPrefix(t,lt) { return t,true } }
	return "",false
