type selTerm struct {
	Explicit bool
	Remove bool
	Tag string // either tag (resolved)
	CPs []rune // or codepoints/ranges (HasCPs distinguishes empty set)
	HasCPs bool
}

func parseSelector(s string) []selTerm {
	// Returns terms; calls fatalParse on error with original messages.
	var terms []selTerm
	i:=0
	explicit:=false; remove:=false; haveOp:=false
	for i<len(s) {
		c:=s[i]
		if c==' '||c=='\t'||c==',' { i++; continue }
		if c=='+' || c=='-' {
			if haveOp { fatalParse("Syntax error in symbol tag selectors.") }
			explicit=true; remove=(c=='-'); haveOp=true; i++; continue
		}
		// a term starts here
		term:=selTerm{Explicit:explicit,Remove:remove}
		if c=='[' {
			// parse set
			cps, consumed := parseBracketSet(s[i:])
			term.CPs=cps; term.HasCPs=true; i+=consumed
		} else if isCodepointStart(s[i:]) {
			cps, consumed := parseCodepointTerm(s[i:])
			term.CPs=cps; term.HasCPs=true; i+=consumed
		} else if isASCIILetter(c) || isDigit(c) {
			start:=i
			for i<len(s) && (isASCIILetter(s[i]) || isDigit(s[i])) { i++ }
			tok:=s[start:i]
