			// Bare hex was handled in isCodepointStart (digit start), so this is a tag or invalid hex token.
			tag, ok := lookupTag(tok)
			if !ok { fatalParse("Unrecognized symbol tag '%s'.", tok) }
			term.Tag=tag
		} else {
