		}
		r, sz := utf8.DecodeRuneInString(s[i:])
		if r==utf8.RuneError && sz==0 { r=rune(s[i]); sz=1 }
		raw=append(raw,r); escaped=append(escaped,false); i+=sz
	}
	fatalParse("Syntax error in symbol selector set.")
	return nil,0
