	// U+hex, 0xhex, or bare hex starting with digit
	if len(s)>=2 && (s[0]=='U'||s[0]=='u') && s[1]=='+' {
		j:=2; start:=j
		for j<len(s)&&isHexDigit(s[j]) { j++ }
		if j==start { return 0,0,false }
		v:=0
		for _,c := range s[start:j] { v=v*16+hexVal(byte(c)); if v>0x2FFFF { /* keep huge but cap for return */ } }
		return rune(v),j,true
	}
	if len(s)>=2 && s[0]=='0' && (s[1]=='x'||s[1]=='X') {
		j:=2; start:=j
		for j<len(s)&&isHexDigit(s[j]) { j++ }
		if j==start { return 0,0,false }
		v:=0; for _,c := range s[start:j] { v=v*16+hexVal(byte(c)) }
		return rune(v),j,true
	}
	if len(s)>=1 && isDigit(s[0]) {
		// bare hex token must be all hex digits and not followed by a non-hex letter.
		j:=0; for j<len(s)&&isHexDigit(s[j]) { j++ }
		if j<len(s) && isASCIILetter(s[j]) { return 0,0,false }
		if j==0 { return 0,0,false }
		v:=0; for _,c := range s[:j] { v=v*16+hexVal(byte(c)) }
		return rune(v),j,true
	}
	return 0,0,false
