func loadImageFile(path string) (*LoadedImage,string) {
	f, err := os.Open(path)
	if err!=nil { return nil, osErrString(err) }
	defer f.Close()
	st, err := f.Stat()
	if err==nil && st.IsDir() { return nil,"Unknown file format" }
	head:=make([]byte,8192)
	n, rerr := io.ReadFull(f,head)
	head=head[:n]
	if rerr!=nil && rerr!=io.ErrUnexpectedEOF && rerr!=io.EOF {
		// e.g. reading a directory handled above; other read errors -> unknown
		return nil,"Unknown file format"
	}
