	if err!=nil { return nil,"Unknown file format" }
	return img,""
}

func osErrString(err error) string {
	if os.IsNotExist(err) { return "No such file or directory" }
	if os.IsPermission(err) { return "Permission denied" }
	// Try to extract syscall errno message, stripping Go wrappers.
	msg:=err.Error()
	// os.PathError format "open X: message"
	if idx:=strings.LastIndex(msg,": "); idx>=0 { msg=msg[idx+2:] }
	if msg!="" { return strings.ToUpper(msg[:1])+msg[1:] }
	return msg
}

