func pointInPoly(x,y float64,pts []svgPoint)bool{ inside:=false; n:=len(pts); for i,j:=0,n-1;i<n;j=i,i++ { xi,yi:=pts[i].x,pts[i].y; xj,yj:=pts[j].x,pts[j].y; if (yi>y)!=(yj>y) { xin:=(xj-xi)*(y-yi)/(yj-yi)+xi; if x<xin { inside=!inside } } }; return inside }
func parsePoints(s string)[]svgPoint{ f:=strings.FieldsFunc(s,func(r rune)bool{return r==' '||r==','||r=='\t'||r=='\n'}); var out []svgPoint; for i:=0;i+1<len(f);i+=2{out=append(out,svgPoint{parseLen(f[i]),parseLen(f[i+1])})}; return out }
func parseSVGTransform(s string, m [6]float64)[6]float64{
