}
func parsePath(d string)[][]svgPoint{
	// Tokenise
	var toks []string; i:=0
	for i<len(d) {
		c:=d[i]
		if c==' '||c==','||c=='\t'||c=='\n'||c=='\r' { i++; continue }
		if (c>='A'&&c<='Z')||(c>='a'&&c<='z') { toks=append(toks,string(c)); i++; continue }
