		j:=i; if d[j]=='+'||d[j]=='-' {j++}; for j<len(d)&&((d[j]>='0'&&d[j]<='9')||d[j]=='.'){j++}; if j<len(d)&&(d[j]=='e'||d[j]=='E'){ j++; if j<len(d)&&(d[j]=='+'||d[j]=='-'){j++}; for j<len(d)&&d[j]>='0'&&d[j]<='9'{j++} }; toks=append(toks,d[i:j]); i=j
	}
