		case 'L': x,y:=num(),num(); if rel{x+=pos.x;y+=pos.y}; pos=svgPoint{x,y}; cur=append(cur,pos)
		case 'H': x:=num(); if rel{x+=pos.x}; pos.x=x; cur=append(cur,pos)
		case 'V': y:=num(); if rel{y+=pos.y}; pos.y=y; cur=append(cur,pos)
		case 'C': x1,y1:=num(),num(); x2,y2:=num(),num(); x,y:=num(),num(); p0:=pos; if rel{x1+=p0.x;y1+=p0.y;x2+=p0.x;y2+=p0.y;x+=p0.x;y+=p0.y}; for t:=1;t<=16;t++{tt:=float64(t)/16; mt:=1-tt; px:=mt*mt*mt*p0.x+3*mt*mt*tt*x1+3*mt*tt*tt*x2+tt*tt*tt*x; py:=mt*mt*mt*p0.y+3*mt*mt*tt*y1+3*mt*tt*tt*y2+tt*tt*tt*y; cur=append(cur,svgPoint{px,py})}; pos=svgPoint{x,y}
