		case 'A': _,_=num(),num(); _=num(); _,_=num(),num(); x,y:=num(),num(); if rel{x+=pos.x;y+=pos.y}; pos=svgPoint{x,y}; cur=append(cur,pos)
		default: idx++ // skip unknown
		}
		// If next token is a command, loop will handle; otherwise repeat same cmd (for M handled by switching to L)
		if idx<len(toks) && isCmd(toks[idx]) { continue }
	}
	flush()
	return polys
}
