package main

import (
	"bytes"
	"encoding/binary"
	"errors"
	"io"
)

// Minimal baseline TIFF decoder: strips or tiles, compression none/PackBits/LZW,
// photometric white/black is zero, RGB and palette, 1/2/4/8/16 bit samples.
func decodeTIFF(data []byte) (*Frame,error) {
	if len(data)<8 { return nil,errors.New("short") }
	var bo binary.ByteOrder
	if data[0]=='I' && data[1]=='I' { bo=binary.LittleEndian } else if data[0]=='M' && data[1]=='M' { bo=binary.BigEndian } else { return nil,errors.New("bad") }
	if bo.Uint16(data[2:4])!=42 { return nil,errors.New("not classic tiff") }
	ifdOff:=int(bo.Uint32(data[4:8]))
	if ifdOff<0 || ifdOff+2>len(data) { return nil,errors.New("bad ifd") }
	n:=int(bo.Uint16(data[ifdOff:ifdOff+2]))
	vals:=map[uint16][]uint32{}
	rawVals:=map[uint16][]byte{}
	typeSizes:=map[uint16]int{1:1,2:1,3:2,4:4,5:8,6:1,7:1,8:2,9:4,10:8,11:4,12:8,13:4,16:8,17:8,18:8}
	for i:=0;i<n;i++ {
		e:=ifdOff+2+i*12
		if e+12>len(data) { return nil,errors.New("ifd trunc") }
		tag:=bo.Uint16(data[e:e+2]); typ:=bo.Uint16(data[e+2:e+4]); count:=int(bo.Uint32(data[e+4:e+8])); sz:=typeSizes[typ]
		if sz==0 || count<0 { continue }
		total:=count*sz
		var raw []byte
		if total<=4 { raw=data[e+8:e+8+total] } else {
			off:=int(bo.Uint32(data[e+8:e+12])); if off<0||off+total>len(data){ return nil,errors.New("val trunc") }; raw=data[off:off+total]
		}
		rawVals[tag]=raw
		var vs []uint32
		for k:=0;k<count;k++ {
			switch typ {
			case 1,2,6,7: vs=append(vs,uint32(raw[k]))
			case 3,8: vs=append(vs,uint32(bo.Uint16(raw[k*2:k*2+2])))
			case 4,9,13: vs=append(vs,bo.Uint32(raw[k*4:k*4+4]))
			case 5,10: num:=bo.Uint32(raw[k*8:k*8+4]); den:=bo.Uint32(raw[k*8+4:k*8+8]); if den!=0 { vs=append(vs,num/den) } else { vs=append(vs,num) }
			default: vs=append(vs,0)
			}
		}
		vals[tag]=vs
	}
	get:=func(tag uint16, def uint32)uint32{ if v,ok:=vals[tag]; ok && len(v)>0 { return v[0] }; return def }
	w:=int(get(256,0)); h:=int(get(257,0)); if w<=0||h<=0 { return nil,errors.New("no size") }
	bpsArr, ok:=vals[258]; if !ok { bpsArr=[]uint32{1} }
	spp:=int(get(277,1)); if spp<=0 { spp=1 }
	for len(bpsArr)<spp { bpsArr=append(bpsArr,bpsArr[len(bpsArr)-1]) }
	compression:=int(get(259,1)); photometric:=int(get(262,2)); planar:=int(get(284,1)); predictor:=int(get(317,1))
	fr:=&Frame{W:w,H:h,Pix:make([]RGBA,w*h)}
	var palette []RGBA
	if raw,ok:=rawVals[320]; ok {
		count:=1<<bpsArr[0]
		if len(raw)>=count*6 {
			palette=make([]RGBA,count)
			for i:=0;i<count;i++ { r:=bo.Uint16(raw[i*2:i*2+2]); g:=bo.Uint16(raw[(count+i)*2:(count+i)*2+2]); b:=bo.Uint16(raw[(2*count+i)*2:(2*count+i)*2+2]); palette[i]=RGBA{uint8(r>>8),uint8(g>>8),uint8(b>>8),255} }
		}
	}
	// Gather segments (strips or tiles)
	type seg struct{x,y,w,h int; data []byte}
	var segs []seg
	_ = seg{}
	type rawseg struct{off,count int}
	var rawsegs []rawseg
	isTiled:=false
	tileW,tileH:=w,h
	if offs,ok:=vals[324]; ok { // TileOffsets
		isTiled=true; tileW=int(get(322,32)); tileH=int(get(323,32))
		counts:=vals[325]
		for i,o:=range offs { c:=0; if i<len(counts){c=int(counts[i])}; rawsegs=append(rawsegs,rawseg{int(o),c}) }
	} else if offs,ok:=vals[273]; ok {
		counts:=vals[279]
		for i,o:=range offs { c:=0; if i<len(counts){c=int(counts[i])}; rawsegs=append(rawsegs,rawseg{int(o),c}) }
	} else { return nil,errors.New("no strips") }
	rowsPerStrip:=int(get(278,0)); if rowsPerStrip<=0 { rowsPerStrip=h }
	segIdx:=0
	planes:=1; if planar==2 { planes=spp }
	// For planar=2, strips are grouped by plane; we process into a 3D sample buffer
	samples:=make([][]uint32,w*h) // per pixel spp samples will be appended in processing order; instead use flat array
	flat:=make([]uint32,w*h*spp)
	_ = samples
	maxBps:=0; for _,b:=range bpsArr { if int(b)>maxBps {maxBps=int(b)} }
	decompress:=func(raw []byte) ([]byte,error){
		switch compression {
		case 1: return raw,nil
		case 32773: return packBitsDecode(raw)
		case 5: return tiffLZWDecode(raw)
		default: return nil,errors.New("unsupported compression")
		}
	}
	readSamples:=func(buf []byte, total int) []uint32 {
		out:=make([]uint32,total)
		bps:=int(bpsArr[0])
		if bps==8 { for i:=0;i<total && i<len(buf);i++ { out[i]=uint32(buf[i]) }; return out }
		if bps==16 { for i:=0;i<total && i*2+2<=len(buf);i++ { out[i]=uint32(bo.Uint16(buf[i*2:i*2+2])) }; return out }
		if bps==32 { for i:=0;i<total && i*4+4<=len(buf);i++ { out[i]=bo.Uint32(buf[i*4:i*4+4]) }; return out }
		// sub-byte, MSB first
		bitpos:=0
		for i:=0;i<total;i++ {
			var v uint32
			for b:=0;b<bits;b++ { byteIdx:=bitpos/8; if byteIdx>=len(buf){return out}; bit:=7-(bitpos%8); v=(v<<1)|uint32((buf[byteIdx]>>bit)&1); bitpos++ }
			out[i]=v
		}
		return out
	}
	for plane:=0; plane<planes; plane++ {
		if isTiled {
			tilesAcross:=(w+tileW-1)/tileW; tilesDown:=(h+tileH-1)/tileH
			for ty:=0;ty<tilesDown;ty++ { for tx:=0;tx<tilesAcross;tx++ {
				if segIdx>=len(rawsegs) { return nil,errors.New("missing tile") }
				rs:=rawsegs[segIdx]; segIdx++
				if rs.off<0||rs.off+rs.count>len(data) { return nil,errors.New("seg oob") }
				dec,err:=decompress(data[rs.off:rs.off+rs.count]); if err!=nil { return nil,err }
				perRow:=tileW*spp; if planar==2 { perRow=tileW }
				ss:=readSamples(dec,tileW*tileH*spp)
				if planar==2 { ss=readSamples(dec,tileW*tileH) }
				si:=0
				for yy:=0;yy<tileH;yy++ {
					y:=ty*tileH+yy
					for xx:=0;xx<tileW;xx++ {
						x:=tx*tileW+xx
						if planar==2 {
							if si<len(ss) { if x<w&&y<h { flat[(y*w+x)*spp+plane]=ss[si] }; si++ }
						} else {
							for s:=0;s<spp;s++ { if si<len(ss) { if x<w&&y<h { flat[(y*w+x)*spp+s]=ss[si] }; si++ } }
						}
					}
				}
			} }
		} else {
			y:=0
			for y<h {
				if segIdx>=len(rawsegs) { return nil,errors.New("missing strip") }
				rs:=rawsegs[segIdx]; segIdx++
				if rs.off<0||rs.off+rs.count>len(data) { return nil,errors.New("seg oob") }
				dec,err:=decompress(data[rs.off:rs.off+rs.count]); if err!=nil { return nil,err }
				rows:=rowsPerStrip; if y+rows>h { rows=h-y }
				var ss []uint32
				if planar==2 { ss=readSamples(dec,w*rows) } else { ss=readSamples(dec,w*rows*spp) }
				// horizontal predictor
				if predictor==2 && (bpsArr[0]==8||bpsArr[0]==16) {
					applyPredictor(ss,w,rows,spp,planar)
				}
				si:=0
				for yy:=0;yy<rows;yy++ { for x:=0;x<w;x++ {
					if planar==2 { if si<len(ss){ flat[((y+yy)*w+x)*spp+plane]=ss[si]; si++ } } else {
						for s:=0;s<spp;s++ { if si<len(ss){ flat[((y+yy)*w+x)*spp+s]=ss[si]; si++ } }
					}
				} }
				y+=rows
				if planar!=2 && y>=h { break }
			}
			if planar==2 {
				// segments for next plane already in rawsegs in order; loop planes resets y but segIdx continues; that is correct because strips grouped by plane. However our y loop for next plane restarts.
				continue
			}
		}
	}
	// Convert samples
	scaleSample:=func(v uint32, bps uint32)uint8{
		if bps==8 { return uint8(v) }; if bps==16 { return uint8(v>>8) }; if bps==1 { if v!=0 {return 255}; return 0 }
		if bps<8 { maxv:=uint32((1<<bps)-1); return uint8((v*255+maxv/2)/maxv) }
		if bps>8 { shift:=bps-8; return uint8(v>>shift) }
		return uint8(v)
	}
	for i:=0;i<w*h;i++ {
		ss:=flat[i*spp:(i+1)*spp]
		var c RGBA
		switch photometric {
		case 3: // palette
			idx:=int(ss[0]); if idx<len(palette) { c=palette[idx] } else { c=RGBA{0,0,0,255} }
			if spp>1 { c.A=scaleSample(ss[spp-1],bpsArr[spp-1]) }
		case 0: // white is zero
			g:=255-scaleSample(ss[0],bpsArr[0]); a:=uint8(255); if spp>1 { a=scaleSample(ss[1],bpsArr[1]) }; c=RGBA{g,g,g,a}
		case 1: // black is zero
			g:=scaleSample(ss[0],bpsArr[0]); a:=uint8(255); if spp>1 { a=scaleSample(ss[1],bpsArr[1]) }; c=RGBA{g,g,g,a}
		default: // RGB (2) and others treated RGB/CMYK-ish
			if spp>=3 {
				a:=uint8(255); if spp>=4 { a=scaleSample(ss[3],bpsArr[3]) }
				// ExtraSamples: if 4th is alpha use it; if spp>4 ignore extras
				c=RGBA{scaleSample(ss[0],bpsArr[0]),scaleSample(ss[1],bpsArr[1]),scaleSample(ss[2],bpsArr[2]),a}
			} else if spp==2 { g:=scaleSample(ss[0],bpsArr[0]); c=RGBA{g,g,g,scaleSample(ss[1],bpsArr[1])} } else { g:=scaleSample(ss[0],bpsArr[0]); c=RGBA{g,g,g,255} }
		}
		fr.Pix[i]=c
	}
	return fr,nil
}

func applyPredictor(ss []uint32,w,rows,spp,planar int){
	if planar==2 {
		for y:=0;y<rows;y++ { for x:=1;x<w;x++ { idx:=y*w+x; if idx<len(ss){ ss[idx]+=ss[idx-1] } } }
	} else {
		for y:=0;y<rows;y++ { for x:=1;x<w;x++ { for s:=0;s<spp;s++ { idx:=(y*w+x)*spp+s; prev:=(y*w+x-1)*spp+s; if idx<len(ss){ ss[idx]+=ss[prev] } } } }
	}
}

func packBitsDecode(data []byte) ([]byte,error) {
	var out bytes.Buffer
	r:=bytes.NewReader(data)
	for {
		b,err:=r.ReadByte(); if err==io.EOF { break }; if err!=nil { return nil,err }
		n:=int(int8(b))
		if n>=0 {
			buf:=make([]byte,n+1); if _,err:=io.ReadFull(r,buf);err!=nil{return nil,err}; out.Write(buf)
		} else if n>=-127 {
			v,err:=r.ReadByte(); if err!=nil{return nil,err}; for i:=0;i<-n+1;i++{out.WriteByte(v)}
		}
	}
	return out.Bytes(),nil
}

// TIFF LZW: MSB-first, early change, codes 256=clear,257=EOI, next=258.
func tiffLZWDecode(data []byte) ([]byte,error) {
	bitpos:=0
	readCode:=func(width int)(int,bool){
		if bitpos+width>len(data)*8 { return 0,false }
		v:=0
		for i:=0;i<width;i++ { byteIdx:=(bitpos+i)/8; bit:=7-((bitpos+i)%8); v=(v<<1)|int((data[byteIdx]>>bit)&1) }
		bitpos+=width; return v,true
	}
	var table [][]byte
	reset:=func(){ table=make([][]byte,258); for i:=0;i<256;i++{table[i]=[]byte{byte(i)}}; table[256]=nil; table[257]=nil }
	reset()
	width:=9; var prev []byte; var out bytes.Buffer
	for {
		code, ok:=readCode(width); if !ok { break }
		if code==256 { reset(); width=9; prev=nil; continue }
		if code==257 { break }
		var entry []byte
		if code < len(table) && table[code]!=nil { entry=table[code] } else if code==len(table) && prev!=nil { entry=append(append([]byte{},prev...),prev[0]) } else { return nil,errors.New("bad lzw code") }
		out.Write(entry)
		if prev!=nil {
			table=append(table, append(append([]byte{},prev...),entry[0]))
			// early change: increase when next code would reach limit
			if len(table)+1 >= (1<<width) && width<12 { width++ }
		}
		prev=append([]byte{},entry...)
	}
	return out.Bytes(),nil
}
