	"errors"
	"unsafe"
)

func decodeWebP(data []byte) (*Frame,error) {
	names:=[]string{"libwebp.so.7","libwebp.so.6","libwebp.so"}
	var handle unsafe.Pointer
	for _, n := range names {
		cn:=C.CString(n); h:=C.open_lib(cn); C.free(unsafe.Pointer(cn))
		if h!=nil { handle=h; break }
