}

func packBitsDecode(data []byte) ([]byte,error) {
	var out bytes.Buffer
	r:=bytes.NewReader(data)
	for {
		b,err:=r.ReadByte(); if err==io.EOF { break }; if err!=nil { return nil,err }
		n:=int(int8(b))
		if n>=0 {
			buf:=make([]byte,n+1); if _,err:=io.ReadFull(r,buf);err!=nil{return nil,err}; out.Write(buf)
		} else if n>=-127 {
			v,err:=r.ReadByte(); if err!=nil{return nil,err}; for i:=0;i<-n+1;i++{out.WriteByte(v)}
		}
	}
	return out.Bytes(),nil
}

// TIFF LZW: MSB-first, early change, codes 256=clear,257=EOI, next=258.
func tiffLZWDecode(data []byte) ([]byte,error) {
	bitpos:=0
	readCode:=func(width int)(int,bool){
		if bitpos+width>len(data)*8 { return 0,false }
		v:=0
		for i:=0;i<width;i++ { byteIdx:=(bitpos+i)/8; bit:=7-((bitpos+i)%8); v=(v<<1)|int((data[byteIdx]>>bit)&1) }
		bitpos+=width; return v,true
	}
	var table [][]byte
	reset:=func(){ table=make([][]byte,258); for i:=0;i<256;i++{table[i]=[]byte{byte(i)}}; table[256]=nil; table[257]=nil }
	reset()
	width:=9; var prev []byte; var out bytes.Buffer
	for {
		code, ok:=readCode(width); if !ok { break }
		if code==256 { reset(); width=9; prev=nil; continue }
		if code==257 { break }
		var entry []byte
		if code < len(table) && table[code]!=nil { entry=table[code] } else if code==len(table) && prev!=nil { entry=append(append([]byte{},prev...),prev[0]) } else { return nil,errors.New("bad lzw code") }
		out.Write(entry)
		if prev!=nil {
			table=append(table, append(append([]byte{},prev...),entry[0]))
			// early change: increase when next code would reach limit
			if len(table)+1 >= (1<<width) && width<12 { width++ }
		}
		prev=append([]byte{},entry...)
	}
	return out.Bytes(),nil
}
