func decodeWebP(data []byte) (*Frame,error) {
	names:=[]string{"libwebp.so.7","libwebp.so.6","libwebp.so"}
	var handle unsafe.Pointer
	for _, n := range names {
		cn:=C.CString(n); h:=C.open_lib(cn); C.free(unsafe.Pointer(cn))
		if h!=nil { handle=h; break }
	}
	if handle==nil { return nil,errors.New("libwebp unavailable") }
	sym:=func(name string)unsafe.Pointer{ cn:=C.CString(name); defer C.free(unsafe.Pointer(cn)); return C.sym_lib(handle,cn) }
	dec:=sym("WebPDecodeRGBA"); freeFn:=sym("WebPFree")
	if dec==nil { return nil,errors.New("WebPDecodeRGBA missing") }
	if len(data)==0 { return nil,errors.New("empty") }
	var w,h C.int
	out:=C.call_decode(dec, (*C.uchar)(unsafe.Pointer(&data[0])), C.size_t(len(data)), &w, &h)
	if out==nil { return nil,errors.New("webp decode failed") }
	defer func(){ if freeFn!=nil { C.call_free(freeFn, unsafe.Pointer(out)) } }()
