	if width<=0||height<=0 { return nil,errors.New("bad webp size") }
	fr:=&Frame{W:width,H:height,Pix:make([]RGBA,width*height)}
	raw:=unsafe.Slice((*byte)(unsafe.Pointer(out)), width*height*4)
	for i:=0;i<width*height;i++ { fr.Pix[i]=RGBA{raw[i*4],raw[i*4+1],raw[i*4+2],raw[i*4+3]} }
	return fr,nil
}
