{"command":"cat > geometry.go << 'EOF'
package main

import "math"

const viewInfinity = 65535

func ceilDivPos(a,b int)int{ if a<=0 {return 1}; return (a+b-1)/b }
func ceilFloat(v float64)int{ if v<=1 {return 1}; return int(math.Ceil(v-1e-9)) }
func minInt(a,b int)int{if a<b{return a};return b}
func maxInt(a,b int)int{if a>b{return a};return b}

func calcFit(srcW,srcH,boxW,boxH int, fr float64, zoom bool, stretch bool)(int,int){
	if srcW<1{srcW=1}; if srcH<1{srcH=1}
	aspect:=float64(srcW)/float64(srcH)
	if stretch {
		w,h:=boxW,boxH
		if w<0 && h<0 { return 1,1 }
		if w<0 { w=ceilFloat(float64(h)*aspect/fr) }
		if h<0 { h=ceilFloat(float64(w)*fr/aspect) }
		return maxInt(1,w),maxInt(1,h)
	}
	if boxW<0 && boxH>=0 {
		h:=boxH
		if !zoom && h>srcH { h=srcH }
		w:=ceilFloat(float64(h)*aspect/fr)
		return maxInt(1,w),maxInt(1,h)
	}
	if boxH<0 && boxW>=0 {
		w:=boxW
		if !zoom && w>srcW { w=srcW }
		h:=ceilFloat(float64(w)*fr/aspect)
		return maxInt(1,w),maxInt(1,h)
	}
	if boxW<0 && boxH<0 { return 1,1 }
	bw,bh:=boxW,boxH
	if !zoom { bw=minInt(bw,srcW); bh=minInt(bh,srcH) }
	hFromW:=ceilFloat(float64(bw)*fr/aspect)
	if hFromW<=bh { return maxInt(1,bw),maxInt(1,hFromW) }
	wFromH:=ceilFloat(float64(bh)*aspect/fr)
	return maxInt(1,wFromH),maxInt(1,bh)
}

type termGeom struct {
	ViewW,ViewH int
	CellPxW,CellPxH int
	Detected bool
}

func effectiveFontRatio(o *Options, tg termGeom) float64 {
	if o.FontRatioSet { return o.FontRatio }
	if tg.CellPxW>0 && tg.CellPxH>0 { return float64(tg.CellPxW)/float64(tg.CellPxH) }
	return 0.5
}

func scaleDesired(srcW,srcH int, scale float64, fr float64, cellPxW,cellPxH int, frSet bool)(int,int){
	if cellPxW<=0{cellPxW=10}; if cellPxH<=0{cellPxH=20}
	if math.IsInf(scale,1) { return viewInfinity,viewInfinity }
	aspect:=float64(srcW)/float64(srcH)
	if frSet {
		// Reference length follows the terminal cell width, as observed in
		// the reference when no terminal pixel size is known.
		effCellW:=float64(cellPxW)
		if fr>1 { effCellW*=fr }
		cols:=ceilFloat(float64(srcW)*scale/effCellW)
		rows:=ceilFloat(float64(cols)*fr/aspect)
		return cols,rows
	}
	cols:=ceilFloat(float64(srcW)*scale/float64(cellPxW))
	rows:=ceilFloat(float64(cols)*fr/aspect)
	// rows computed from cols gives geometric consistency; if the terminal
	// cell ratio differs it still matches direct division closely.
	_ = cellPxH
	return cols,rows
}

// canvasSize returns cols,rows for an image, ignoring grid layout.
func canvasSize(o *Options, tg termGeom, srcW,srcH int, format Format)(int,int){
	fr:=effectiveFontRatio(o,tg)
	cellW:=tg.CellPxW; if cellW<=0{cellW=10}; cellH:=tg.CellPxH; if cellH<=0{cellH=20}
	if o.Exact==TriOn {
		return ceilDivPos(srcW,cellW), ceilDivPos(srcH,cellH)
	}
	// Effective view box
	viewW:=tg.ViewW; viewH:=tg.ViewH
	if o.ViewSet {
		viewW=o.ViewW; if viewW<0{viewW=viewInfinity}
		viewH=o.ViewH; if viewH<0{viewH=viewInfinity}
	}
	effViewW:=viewW-o.MarginRight; if effViewW<1{effViewW=1}
	effViewH:=viewH-o.MarginBottom; if effViewH<1{effViewH=1}
	if o.SizeSet {
		boxW,boxH:=o.SizeW,o.SizeH
		if o.Stretch { return calcFit(srcW,srcH,boxW,boxH,fr,true,true) }
		if o.ScaleMax { return calcFit(srcW,srcH,boxW,boxH,fr,true,false) }
		if o.FitWidth {
			// Fit-width with explicit size behaves like size alone (observed).
			return calcFit(srcW,srcH,boxW,boxH,fr,false,false)
		}
		return calcFit(srcW,srcH,boxW,boxH,fr,false,false)
	}
	// No explicit size: box is effective view.
	boxW,boxH:=effViewW,effViewH
	if o.Stretch { return calcFit(srcW,srcH,boxW,boxH,fr,true,true) }
	if o.FitWidth { return calcFit(srcW,srcH,boxW,-1,fr,true,false) }
	if o.ScaleMax { return calcFit(srcW,srcH,boxW,boxH,fr,true,false) }
	scale:=o.Scale
	if !o.ScaleSet { if format==FormatSymbols { scale=4 } else { scale=1 } }
	dw,dh:=scaleDesired(srcW,srcH,scale,fr,cellW,cellH,o.FontRatioSet)
	if dw<=boxW && dh<=boxH { return dw,dh }
	return calcFit(srcW,srcH,boxW,boxH,fr,true,false)
}

func stretchToInfinity(o *Options) bool {
	if !o.Stretch && !o.FitWidth { return false }
	if o.SizeSet { return false }
	// Without size, effective width/height derive from view.
	viewWInf:=false; viewHInf:=false
	if o.ViewSet {
		if o.ViewW<0 { viewWInf=true }
		if o.ViewH<0 { viewHInf=true }
	} else {
		// Terminal-detected / fallback view is finite in non-tty path. In tty path main may refine.
		return false
	}
	if o.Stretch && (viewWInf||viewHInf) { return true }
	if o.FitWidth && viewWInf { return true }
	return false
}
EOF"}

