{"command":"cat > scale.go << 'EOF'
package main

import "math"

var srgbToLinTable [256]float64
func init(){
	for i:=0;i<256;i++ { v:=float64(i)/255; if v<=0.04045 { srgbToLinTable[i]=v/12.92 } else { srgbToLinTable[i]=math.Pow((v+0.055)/1.055,2.4) } }
}
func linToSrgbByte(v float64)uint8{
	if v<=0 { return 0 }
	if v>=1 { /* may exceed 1 for saturated */ }
	var s float64
	if v<=0.0031308 { s=v*12.92 } else { s=1.055*math.Pow(v,1.0/2.4)-0.055 }
	x:=int(math.Round(s*255))
	if x<0{x=0}; if x>255{x=255}; return uint8(x)
}

type axisWeight struct{ idx int; w float64 }

func axisWeights(src,dst int) [][]axisWeight {
	out:=make([][]axisWeight,dst)
	if src==dst { for i:=0;i<dst;i++{out[i]=[]axisWeight{{i,1}}}; return out }
	if dst>src {
		// bilinear, aligned corners
		for i:=0;i<dst;i++ {
			if dst==1 || src==1 { out[i]=[]axisWeight{{0,1}}; continue }
			pos:=float64(i)*float64(src-1)/float64(dst-1)
			lo:=int(math.Floor(pos)); frac:=pos-float64(lo)
			if lo>=src-1 { out[i]=[]axisWeight{{src-1,1}} } else if frac==0 { out[i]=[]axisWeight{{lo,1}} } else { out[i]=[]axisWeight{{lo,1-frac},{lo+1,frac}} }
		}
		return out
	}
	// downscale: bilinear to dst*m (pixel-centre mapping), then box average by m.
	ratio:=float64(src)/float64(dst)
	m:=1
	for m*2<=int(math.Floor(ratio)) { m*=2 }
	// largest power of two <= ratio (for ratio<2, m=1). The loop above based on floor may stop early for e.g. ratio 3 -> m=2 correct; ratio 5 -> m=4.
	inter:=dst*m
	interWeights:=make([][]axisWeight,inter)
	for j:=0;j<inter;j++ {
