{"command":"cat > terminal.go << 'EOF'
package main

import (
	"os"
	"strconv"
	"strings"
	"syscall"
	"unsafe"
)

type termProfile struct {
	Detected bool // false = safe fallback (no terminal info)
	Name string
	Format Format
	Colors ColorMode
	// Symbol tags expression applied to an empty set (first bare term semantics handled by caller using DefaultTags list)
	DefaultTags []string
	CellPxW,CellPxH int
	CursorSeq bool // whether hide/show etc are emitted (subject to polite/none)
	ClearSeq string
	SixelInit string
	Hyperlink bool
	BoldForBright bool // 16/8 style: use bold for bright fg (and blink confusion) rather than bright SGR
	BlinkForBrightBg bool
}

type winSize struct{ Rows,Cols,XPixel,YPixel uint16 }

func ioctlWinsize(fd uintptr)(winSize,bool){
	var ws winSize
	_,_,errno:=syscall.Syscall(syscall.SYS_IOCTL,fd,uintptr(0x5413),uintptr(unsafe.Pointer(&ws)))
	if errno!=0 { return ws,false }
	if ws.Cols==0||ws.Rows==0 { return ws,false }
	return ws,true
}

func getTerminalGeom() termGeom {
	// Try stdout, then /dev/tty, then stdin/stderr.
	try:=func(fd uintptr)(termGeom,bool){
		ws,ok:=ioctlWinsize(fd); if !ok{return termGeom{},false}
		g:=termGeom{ViewW:int(ws.Cols),ViewH:int(ws.Rows),CellPxW:10,CellPxH:20,Detected:true}
		if ws.XPixel>0&&ws.Cols>0 { g.CellPxW=int(ws.XPixel)/int(ws.Cols); if g.CellPxW<1{g.CellPxW=1} }
		if ws.YPixel>0&&ws.Rows>0 { g.CellPxH=int(ws.YPixel)/int(ws.Rows); if g.CellPxH<1{g.CellPxH=1} }
		return g,true
	}
	if g,ok:=try(os.Stdout.Fd()); ok { return g }
	if f,err:=os.OpenFile("/dev/tty",os.O_RDWR,0); err==nil { g,ok:=try(f.Fd()); f.Close(); if ok{return g} }
	if g,ok:=try(os.Stdin.Fd()); ok { return g }
	if g,ok:=try(os.Stderr.Fd()); ok { return g }
	g:=termGeom{ViewW:80,ViewH:25,CellPxW:10,CellPxH:20,Detected:false}
	if v,ok:=os.LookupEnv("COLUMNS"); ok {
		// atoi-style prefix
		s:=strings.TrimLeft(v," \t")
		n:=0; sign:=1; i:=0
		if i<len(s)&&(s[i]=='+'||s[i]=='-'){ if s[i]=='-'{sign=-1}; i++ }
		start:=i; val:=0
		for ; i<len(s)&&s[i]>='0'&&s[i]<='9'; i++ { val=val*10+int(s[i]-'0') }
		if i>start { n=sign*val }
		if n>0 && n<1000000 { g.ViewW=n }
		_ = strconv.Itoa
	}
	return g
}

func isTTY(f *os.File)bool{ _,ok:=ioctlWinsize(f.Fd()); return ok }

func detectProfile() termProfile {
	safe:=termProfile{Detected:false,Name:"safe",Format:FormatSymbols,Colors:ColorsNone,DefaultTags:[]string{"ascii"},CellPxW:10,CellPxH:20}
	term, termPresent := os.LookupEnv("TERM")
	prog := os.Getenv("TERM_PROGRAM")
	lt:=strings.ToLower(term); lp:=strings.ToLower(prog)
	// Specific program-based profiles first.
	if lp=="iterm.app" || strings.Contains(lp,"iterm") {
		return termProfile{Detected:true,Name:"iterm",Format:FormatIterm,Colors:ColorsFull,DefaultTags:[]string{"block","border","diagonal"},CellPxW:10,CellPxH:20,CursorSeq:true,ClearSeq:"\x1b[2J\x1b[0H",Hyperlink:true}
	}
	if lp=="wezterm" {
		return termProfile{Detected:true,Name:"wezterm",Format:FormatSixels,Colors:ColorsFull,DefaultTags:[]string{"block","border","diagonal"},CellPxW:10,CellPxH:20,CursorSeq:true,ClearSeq:"\x1b[2J\x1b[0H",SixelInit:"\x1b[?80l\x1b[?8452l",Hyperlink:true}
	}
	if prog!="" && (strings.Contains(lp,"kitty")) {
		return termProfile{Detected:true,Name:"kitty",Format:FormatKitty,Colors:ColorsFull,DefaultTags:[]string{"block","border","diagonal"},CellPxW:10,CellPxH:20,CursorSeq:true,ClearSeq:"\x1b[2J\x1b[0H",Hyperlink:true}
	}
	if os.Getenv("VTE_VERSION")!="" || os.Getenv("KONSOLE_VERSION")!="" {
		return unicodeProfile("vte")
	}
	if !termPresent {
		return safe
	}
	// TERM-based classification.
	switch {
	case strings.Contains(lt,"kitty"):
		return termProfile{Detected:true,Name:"kitty",Format:FormatKitty,Colors:ColorsFull,DefaultTags:[]string{"block","border","diagonal"},CellPxW:10,CellPxH:20,CursorSeq:true,ClearSeq:"\x1b[2J\x1b[0H",Hyperlink:true}
	case lt=="foot" || strings.HasPrefix(lt,"foot-") || lt=="foot-extra":
		return termProfile{Detected:true,Name:"foot",Format:FormatSixels,Colors:ColorsFull,DefaultTags:[]string{"block","border","diagonal"},CellPxW:10,CellPxH:20,CursorSeq:true,ClearSeq:"\x1b[2J\x1b[0H",SixelInit:"\x1b[?80l\x1b[?8452l",Hyperlink:true}
	case lt=="linux":
		return termProfile{Detected:true,Name:"linux",Format:FormatSymbols,Colors:Colors16,DefaultTags:[]string{"ascii"},CellPxW:10,CellPxH:20,CursorSeq:true,ClearSeq:"\x1b[2J\x1b[0H"}
	case strings.HasPrefix(lt,"screen"):
		return termProfile{Detected:true,Name:"screen",Format:FormatSymbols,Colors:Colors256,DefaultTags:[]string{"ascii"},CellPxW:10,CellPxH:20,CursorSeq:true,ClearSeq:"\x1b[2J\x1b[0H"}
	case isUnicodeTerm(lt):
		return unicodeProfile(lt)
	default:
		// Generic fallback for any other TERM value.
		return termProfile{Detected:true,Name:"generic",Format:FormatSymbols,Colors:Colors16_8,DefaultTags:[]string{"ascii"},CellPxW:10,CellPxH:20,CursorSeq:true,ClearSeq:"\x1b[2J\x1b[0H",BoldForBright:true,BlinkForBrightBg:false}
	}
}

func unicodeProfile(name string) termProfile {
	return termProfile{Detected:true,Name:name,Format:FormatSymbols,Colors:ColorsFull,DefaultTags:[]string{"block","border","diagonal"},CellPxW:10,CellPxH:20,CursorSeq:true,ClearSeq:"\x1b[2J\x1b[0H",Hyperlink:false}
}
func isUnicodeTerm(lt string)bool{
	if lt=="xterm"||strings.HasPrefix(lt,"xterm-") { return true }
	prefixes:=[]string{"rxvt-unicode","alacritty","gnome","konsole","st-","terminator","tilix","pantheon","xfce","mlterm","putty","cygwin","msys","foot","contour","ghostty","rio","tabby"}
	for _,p:=range prefixes { if lt==p||strings.HasPrefix(lt,p) { 
		// Observed: contour/ghostty as bare TERM fell back to generic in probe-off tests, so exclude them there.
		if lt=="contour"||lt=="ghostty" { return false }
		return true } }
	if strings.Contains(lt,"256color") && (strings.HasPrefix(lt,"xterm")||strings.HasPrefix(lt,"rxvt")) { return true }
	return false
}

func applyProbedSize(g *termGeom, cols,rows,cellW,cellH int) {
	if cols>0 { g.ViewW=cols }; if rows>0 { g.ViewH=rows }
	if cellW>0 { g.CellPxW=cellW }; if cellH>0 { g.CellPxH=cellH }
}
EOF"}

