package main

import (
	"math"
	"sort"
)

type CellColor struct {
	Transparent bool
	R,G,B uint8
	Index int // palette index if HasIndex
	HasIndex bool
}
func rgbColor(c RGBA) CellColor { return CellColor{R:c.R,G:c.G,B:c.B} }
func (c CellColor) RGBA() RGBA { return RGBA{c.R,c.G,c.B,255} }

type Cell struct {
	Ch rune
	Fg,Bg CellColor
	Width int
}
type Canvas struct {
	W,H int
	Cells []Cell
	// For pixel formats
	Pix *Frame
	PixCols,PixRows int // cells
}

type canvasConfig struct {
	Opts *Options
	Profile termProfile
	Format Format
	Colors ColorMode
	Symbols []*Glyph
	FillSymbols []*Glyph
	FgDefault RGBA
	BgDefault RGBA
	Preprocess bool
	Dither string
}

func (cc *canvasConfig) isTransparentAlpha(a uint8) bool {
	t:=cc.Opts.Threshold
	// Observed mapping: transparent if (a+1) <= (1-t)*256
	return float64(int(a)+1) <= (1-t)*256
}

func composite(c RGBA, bg RGBA) RGBA {
	a:=int(c.A)
	return RGBA{uint8((int(c.R)*a+int(bg.R)*(255-a))/255),uint8((int(c.G)*a+int(bg.G)*(255-a))/255),uint8((int(c.B)*a+int(bg.B)*(255-a))/255),255}
}

type subPixel struct {
	col RGBA // composited if opaque
	transparent bool
}

func (cc *canvasConfig) extract(pixels []subPixel, mask uint64, wantFg bool) CellColor {
	var vals []RGBA
	for i:=0;i<64;i++ {
		bit:=(mask>>uint(i))&1==1
		if bit!=wantFg { continue }
		if !pixels[i].transparent { vals=append(vals,pixels[i].col) }
	}
	if len(vals)==0 { return CellColor{Transparent:true,Index:1,HasIndex:true} }
	if cc.Opts.ColorExtractor=="median" {
		rs:=make([]int,len(vals)); gs:=make([]int,len(vals)); bs:=make([]int,len(vals))
		for i,v:=range vals { rs[i]=int(v.R); gs[i]=int(v.G); bs[i]=int(v.B) }
		sort.Ints(rs);sort.Ints(gs);sort.Ints(bs)
		mid:=len(vals)/2
		return rgbColor(RGBA{uint8(rs[mid]),uint8(gs[mid]),uint8(bs[mid]),255})
	}
	var sr,sg,sb int
	for _,v:=range vals { sr+=int(v.R);sg+=int(v.G);sb+=int(v.B) }
	n:=len(vals)
	avg:=func(s int)uint8{ return uint8((s+n/2)/n) }
	return rgbColor(RGBA{avg(sr),avg(sg),avg(sb),255})
}

func (cc *canvasConfig) quantize(c CellColor, isFg bool) CellColor {
	if c.Transparent { return c }
	rgb:=c.RGBA()
	switch cc.Colors {
	case ColorsFull:
		return c
	case Colors256,Colors240:
		idx:=nearestPalette(rgb,cc.Colors,cc.Opts.ColorSpace)
		p:=palette256[idx]; return CellColor{R:uint8(p[0]),G:uint8(p[1]),B:uint8(p[2]),Index:idx,HasIndex:true}
	case Colors16:
		idx:=nearestPalette(rgb,Colors16,cc.Opts.ColorSpace)
		p:=palette256[idx]; return CellColor{R:uint8(p[0]),G:uint8(p[1]),B:uint8(p[2]),Index:idx,HasIndex:true}
	case Colors8:
		idx:=nearestPalette(rgb,Colors16,cc.Opts.ColorSpace); if idx>=8 { idx-=8 } // nearest among first 8 would be better; redo:
		idx=nearestAmong(rgb,cc.Opts.ColorSpace,0,7)
		p:=palette256[idx]; return CellColor{R:uint8(p[0]),G:uint8(p[1]),B:uint8(p[2]),Index:idx,HasIndex:true}
	case Colors16_8:
		var idx int
		if isFg { idx=nearestAmong(rgb,cc.Opts.ColorSpace,0,15) } else { idx=nearestAmong(rgb,cc.Opts.ColorSpace,0,7) }
		p:=palette256[idx]; return CellColor{R:uint8(p[0]),G:uint8(p[1]),B:uint8(p[2]),Index:idx,HasIndex:true}
	case Colors2,ColorsNone:
		// nearest of default fg/bg
		dfg:=cc.FgDefault; dbg:=cc.BgDefault
		v:=rgbToVec(rgb,cc.Opts.ColorSpace)
		if colorDist2(v,rgbToVec(dfg,cc.Opts.ColorSpace)) <= colorDist2(v,rgbToVec(dbg,cc.Opts.ColorSpace)) {
			return CellColor{R:dfg.R,G:dfg.G,B:dfg.B,Index:1,HasIndex:true}
		}
		return CellColor{R:dbg.R,G:dbg.G,B:dbg.B,Index:0,HasIndex:true}
	}
	return c
}
func nearestAmong(rgb RGBA, space string, lo,hi int)int{
	initPalette(); v:=rgbToVec(rgb,space); best:=lo; bd:=math.Inf(1)
	for i:=lo;i<=hi;i++ { d:=colorDist2(v,paletteVec(i,space)); if d<bd{bd=d;best=i} }
	return best
}

func (cc *canvasConfig) colorError(p subPixel, rend CellColor) float64 {
	if p.transparent && rend.Transparent { return 0 }
	if p.transparent != rend.Transparent {
		var o RGBA; if p.transparent { o=rend.RGBA() } else { o=p.col }
		// premultiplied RGBA distance to transparent black
		return float64(int(o.R)*int(o.R)+int(o.G)*int(o.G)+int(o.B)*int(o.B)+255*255)
	}
	if cc.Opts.ColorSpace=="din99d" {
		return colorDist2(rgbToVec(p.col,"din99d"),rgbToVec(rend.RGBA(),"din99d"))*100 // scale roughly to RGB magnitudes
	}
	dr:=float64(int(p.col.R)-int(rend.R)); dg:=float64(int(p.col.G)-int(rend.G)); db:=float64(int(p.col.B)-int(rend.B))
	return dr*dr+dg*dg+db*db
}

func (cc *canvasConfig) pickCell(pixels []subPixel) Cell {
	// Special handling for colour mode none is folded into the general
	// evaluation by quantize() mapping extracted colours to fg/bg defaults.
	bestErr:=math.Inf(1); var best Cell; haveBest:=false
	candidates:=cc.Symbols
	if len(candidates)==0 { candidates=[]*Glyph{glyphByCP[' ']} }
	for _, g := range candidates {
		if g.Width!=1 { continue }
		fgRaw:=cc.extract(pixels,g.Bits,true)
		bgRaw:=cc.extract(pixels,g.Bits,false)
		var fg,bg CellColor
		if cc.Colors==ColorsNone {
			// Render with fixed defaults (but keep extracted for tie purposes?)
			// If a partition is entirely transparent, rendered colour is transparent.
			if fgRaw.Transparent { fg=fgRaw } else { fg=rgbColor(cc.FgDefault); fg.Index=1; fg.HasIndex=true }
			if bgRaw.Transparent { bg=bgRaw } else { bg=rgbColor(cc.BgDefault); bg.Index=0; bg.HasIndex=true }
			// If mask partition is empty, extract returns transparent; that's fine as it is unused.
		} else {
			fg=cc.quantize(fgRaw,true); bg=cc.quantize(bgRaw,false)
			if cc.Opts.FgOnly { bg=CellColor{Transparent:true,Index:1,HasIndex:true} }
		}
		err:=0.0
		for i:=0;i<64;i++ {
			bit:=(g.Bits>>uint(i))&1==1
			var rend CellColor; if bit { rend=fg } else { rend=bg }
			err+=cc.colorError(pixels[i],rend)
		}
		if !haveBest || err<bestErr-1e-9 {
			bestErr=err; best=Cell{Ch:g.CP,Fg:fg,Bg:bg,Width:1}; haveBest=true
		}
	}
	if !haveBest { return Cell{Ch:' ',Fg:CellColor{Transparent:true},Bg:CellColor{Transparent:true},Width:1} }
	return best
}

func (cc *canvasConfig) makeSymbolCanvas(src *Frame, cols,rows int) *Canvas {
	scaled:=scaleFrame(src,cols*8,rows*8)
	cc.applyDither(scaled)
	canv:=&Canvas{W:cols,H:rows,Cells:make([]Cell,cols*rows)}
	for cy:=0;cy<rows;cy++ {
		// Median extractor in the original appears to carry a previous fg
		// colour across a row for empty partitions; approximate in printer layer.
		for cx:=0;cx<cols;cx++ {
			var pixels [64]subPixel
			for y:=0;y<8;y++ { for x:=0;x<8;x++ {
				p:=scaled.Pix[(cy*8+y)*scaled.W+(cx*8+x)]
				if cc.isTransparentAlpha(p.A) { pixels[y*8+x]=subPixel{transparent:true} } else { pixels[y*8+x]=subPixel{col:composite(p,cc.BgDefault)} }
			} }
			canv.Cells[cy*cols+cx]=cc.pickCell(pixels[:])
		}
	}
	return canv
}

func (cc *canvasConfig) applyDither(f *Frame) {
	mode:=cc.Dither
	if mode==""||mode=="none" { return }
	if cc.Colors==ColorsFull { return }
	// Grain size in subpixels: grain dimensions are in 1/8 cell, a cell is 8 subpixels,
	// so grain subpixels = grain value (1,2,4,8).
	gw:=cc.Opts.DitherGrainW; gh:=cc.Opts.DitherGrainH
	if gw<1{gw=1}; if gh<1{gh=1}
	intensity:=cc.Opts.DitherIntensity
	bayer:=[4][4]int{{0,8,2,10},{12,4,14,6},{3,11,1,9},{15,7,13,5}}
	for gy:=0;gy<f.H;gy+=gh {
		for gx:=0;gx<f.W;gx+=gw {
			var off float64
