			case "ordered":
				off=(float64(bayer[(gy/gh)%4][(gx/gw)%4])/16.0-0.5)*32*intensity
			case "noise","diffusion":
				// deterministic hash noise per grain (diffusion approximated as noise here)
				h:=uint32(gx*374761393+gy*668265263); h=(h^(h>>13))*1274126177; h=h^(h>>16)
				off=(float64(h%1000)/1000.0-0.5)*32*intensity
			}
			if off==0 { continue }
			for y:=gy;y<gy+gh&&y<f.H;y++ { for x:=gx;x<gx+gw&&x<f.W;x++ {
				p:=&f.Pix[y*f.W+x]
				if p.A==0 { continue }
				p.R=clamp255(int(float64(p.R)+off)); p.G=clamp255(int(float64(p.G)+off)); p.B=clamp255(int(float64(p.B)+off))
			} }
		}
	}
}

func (cc *canvasConfig) makePixelCanvas(src *Frame, cols,rows int, tg termGeom, paintExact bool) *Canvas {
	cellW:=tg.CellPxW; if cellW<=0{cellW=10}; cellH:=tg.CellPxH; if cellH<=0{cellH=20}
	pixW:=cols*cellW; pixH:=rows*cellH
	buf:=&Frame{W:pixW,H:pixH,Pix:make([]RGBA,pixW*pixH)}
	if paintExact {
		// Paste at original size, top-left, cropping if needed.
		for y:=0;y<src.H&&y<pixH;y++ { for x:=0;x<src.W&&x<pixW;x++ { buf.Pix[y*pixW+x]=src.Pix[y*src.W+x] } }
	} else {
		var dw,dh int
		if cc.Opts.Stretch { dw,dh=pixW,pixH } else {
			// fit preserving aspect
			scale:=math.Min(float64(pixW)/float64(src.W),float64(pixH)/float64(src.H))
			dw=int(math.Round(float64(src.W)*scale)); dh=int(math.Round(float64(src.H)*scale))
			if dw<1{dw=1}; if dh<1{dh=1}; if dw>pixW{dw=pixW}; if dh>pixH{dh=pixH}
		}
		scaled:=scaleFrame(src,dw,dh)
		for y:=0;y<dh;y++ { for x:=0;x<dw;x++ { buf.Pix[y*pixW+x]=scaled.Pix[y*dw+x] } }
	}
	return &Canvas{W:cols,H:rows,Pix:buf,PixCols:cols,PixRows:rows}
}
EOF"}

