func colorEqual(a,b CellColor)bool{ return a.Transparent==b.Transparent && a.R==b.R && a.G==b.G && a.B==b.B && a.Index==b.Index && a.HasIndex==b.HasIndex }

func sgrColorParams(c CellColor, isFg bool, mode ColorMode, prof termProfile) (string,bool) {
	// returns params without ESC[ ]m and bold needed for 16/8 bright fg
	if c.Transparent { return "",false }
	switch mode {
	case ColorsFull:
		if isFg { return fmt.Sprintf("38;2;%d;%d;%d",c.R,c.G,c.B),false }
		return fmt.Sprintf("48;2;%d;%d;%d",c.R,c.G,c.B),false
