		idx:=c.Index
		if isFg { if idx<8{return fmt.Sprint(30+idx),false}; return fmt.Sprint(90+idx-8),false }
		if idx<8{return fmt.Sprint(40+idx),false}; return fmt.Sprint(100+idx-8),false
	case Colors8:
		idx:=c.Index; if idx>7{idx-=8}
		if isFg{return fmt.Sprint(30+idx),false}; return fmt.Sprint(40+idx),false
	case Colors16_8:
		idx:=c.Index
		if prof.BoldForBright {
