		if isFg { if idx<8{return fmt.Sprint(30+idx),false}; return fmt.Sprint(90+idx-8),false }
		if idx>7{idx-=8}; return fmt.Sprint(40+idx),false
	}
	return "",false
}

func sentinelFg(mode ColorMode) CellColor {
	switch mode {
	case ColorsFull: return CellColor{R:0,G:0,B:0}
	case Colors256,Colors240: p:=palette256[1]; return CellColor{R:uint8(p[0]),G:uint8(p[1]),B:uint8(p[2]),Index:1,HasIndex:true}
	case Colors16,Colors16_8,Colors8: p:=palette256[1]; return CellColor{R:uint8(p[0]),G:uint8(p[1]),B:uint8(p[2]),Index:1,HasIndex:true}
	}
	return CellColor{Transparent:true}
}

func printSymbolCanvas(buf *bytes.Buffer, canv *Canvas, cc *canvasConfig, hoffset int) {
	o:=cc.Opts; prof:=cc.Profile; mode:=cc.Colors
	if hoffset>4096 { hoffset=4096 }
	pad:=strings.Repeat(" ",hoffset)
	if mode==ColorsNone {
		for y:=0;y<canv.H;y++ {
			if hoffset>0 { buf.WriteString(pad) }
			for x:=0;x<canv.W; {
				c:=canv.Cells[y*canv.W+x]; buf.WriteRune(c.Ch); if c.Width>1{x+=c.Width}else{x++}
			}
			if o.Relative {
				if y<canv.H-1 { fmt.Fprintf(buf,"\x1b[%dD\x1bD",canv.W) } else { fmt.Fprintf(buf,"\x1bD\x1b[%dD",canv.W) }
			} else { buf.WriteByte('\n') }
		}
		return
	}
	opt:=o.Optimize
	if !o.OptimizeSet { opt=5 }
	if opt==0 {
		printSymbolCanvasOpt0(buf,canv,cc,hoffset)
		return
	}
	// opt >=1
	buf.WriteString("\x1b[0m")
