				if cell.Fg.Transparent {
					if pen.fgSet||pen.bgSet||pen.bold||pen.blink { buf.WriteString("\x1b[0m"); pen=penState{} }
					fgParam,_:=sgrColorParams(cell.Bg,true,mode,prof)
					buf.WriteString("\x1b[7m")
					if fgParam!="" { fmt.Fprintf(buf,"\x1b[%sm",fgParam) }
					buf.WriteByte(' ')
					buf.WriteString("\x1b[0m")
					pen=penState{}
					x+=w; continue
				}
			}
			if mode==Colors2 {
				printCellColors2(buf,cell,cc,&pen)
