			if !desiredFg.Transparent { if p,_:=sgrColorParams(desiredFg,true,mode,prof);p!=""{params=append(params,p)} }
			if !isFullBlock && !desiredBg.Transparent { if p,_:=sgrColorParams(desiredBg,false,mode,prof);p!=""{params=append(params,p)} }
			if len(params)>0 { fmt.Fprintf(buf,"\x1b[%sm",strings.Join(params,";")) }
