{"command":"cat > print.go << 'EOF'
package main

import (
	"bytes"
	"fmt"
	"strings"
)

type penState struct {
	fgSet,bgSet bool
	fg,bg CellColor
	bold bool
	reverse bool
	blink bool
}

func colorEqual(a,b CellColor)bool{ return a.Transparent==b.Transparent && a.R==b.R && a.G==b.G && a.B==b.B && a.Index==b.Index && a.HasIndex==b.HasIndex }

func sgrColorParams(c CellColor, isFg bool, mode ColorMode, prof termProfile) (string,bool) {
	// returns params without ESC[ ]m and bold needed for 16/8 bright fg
	if c.Transparent { return "",false }
	switch mode {
	case ColorsFull:
		if isFg { return fmt.Sprintf("38;2;%d;%d;%d",c.R,c.G,c.B),false }
		return fmt.Sprintf("48;2;%d;%d;%d",c.R,c.G,c.B),false
	case Colors256,Colors240:
		if isFg { return fmt.Sprintf("38;5;%d",c.Index),false }
		return fmt.Sprintf("48;5;%d",c.Index),false
	case Colors16:
		idx:=c.Index
		if isFg { if idx<8{return fmt.Sprint(30+idx),false}; return fmt.Sprint(90+idx-8),false }
		if idx<8{return fmt.Sprint(40+idx),false}; return fmt.Sprint(100+idx-8),false
	case Colors8:
		idx:=c.Index; if idx>7{idx-=8}
		if isFg{return fmt.Sprint(30+idx),false}; return fmt.Sprint(40+idx),false
	case Colors16_8:
		idx:=c.Index
		if prof.BoldForBright {
			if isFg { if idx<8{return fmt.Sprint(30+idx),false}; return fmt.Sprint(30+idx-8),true }
			if idx>7{idx-=8}; return fmt.Sprint(40+idx),false
		}
		// Bright via 90/100 for fg; bg only normal.
		if isFg { if idx<8{return fmt.Sprint(30+idx),false}; return fmt.Sprint(90+idx-8),false }
		if idx>7{idx-=8}; return fmt.Sprint(40+idx),false
	}
	return "",false
}

func sentinelFg(mode ColorMode) CellColor {
	switch mode {
	case ColorsFull: return CellColor{R:0,G:0,B:0}
	case Colors256,Colors240: p:=palette256[1]; return CellColor{R:uint8(p[0]),G:uint8(p[1]),B:uint8(p[2]),Index:1,HasIndex:true}
	case Colors16,Colors16_8,Colors8: p:=palette256[1]; return CellColor{R:uint8(p[0]),G:uint8(p[1]),B:uint8(p[2]),Index:1,HasIndex:true}
	}
	return CellColor{Transparent:true}
}

func printSymbolCanvas(buf *bytes.Buffer, canv *Canvas, cc *canvasConfig, hoffset int) {
	o:=cc.Opts; prof:=cc.Profile; mode:=cc.Colors
	if hoffset>4096 { hoffset=4096 }
	pad:=strings.Repeat(" ",hoffset)
	if mode==ColorsNone {
		for y:=0;y<canv.H;y++ {
			if hoffset>0 { buf.WriteString(pad) }
			for x:=0;x<canv.W; {
				c:=canv.Cells[y*canv.W+x]; buf.WriteRune(c.Ch); if c.Width>1{x+=c.Width}else{x++}
			}
			if o.Relative {
				if y<canv.H-1 { fmt.Fprintf(buf,"\x1b[%dD\x1bD",canv.W) } else { fmt.Fprintf(buf,"\x1bD\x1b[%dD",canv.W) }
			} else { buf.WriteByte('\n') }
		}
		return
	}
	opt:=o.Optimize
	if !o.OptimizeSet { opt=5 }
	if opt==0 {
		printSymbolCanvasOpt0(buf,canv,cc,hoffset)
		return
	}
	// opt >=1
	buf.WriteString("\x1b[0m")
	pen:=penState{}
	for y:=0;y<canv.H;y++ {
		if hoffset>0 { buf.WriteString(pad) }
		for x:=0;x<canv.W; {
			cell:=canv.Cells[y*canv.W+x]
			w:=cell.Width; if w<1{w=1}
			// Reverse-video trick for a leading space cell (observed behaviour).
			if x==0 && cell.Ch==' ' && !cell.Bg.Transparent && !o.FgOnly && mode!=Colors16_8 && mode!=Colors2 {
				// Only when foreground is transparent/empty (space glyph).
				if cell.Fg.Transparent {
					if pen.fgSet||pen.bgSet||pen.bold||pen.blink { buf.WriteString("\x1b[0m"); pen=penState{} }
