			if pen.reverse { needReset=true }
			if pen.blink { needReset=true }
			if desiredFg.Transparent && pen.fgSet { needReset=true }
			if desiredBg.Transparent && pen.bgSet && !isFullBlock { needReset=true }
			if needReset { buf.WriteString("\x1b[0m"); pen=penState{} }
			// attributes
			if fgBold && !pen.bold { buf.WriteString("\x1b[1m"); pen.bold=true }
			var params []string
