				if p,_:=sgrColorParams(desiredFg,true,mode,prof); p!="" { params=append(params,p); pen.fg=desiredFg; pen.fgSet=true }
			}
			if !isFullBlock && !desiredBg.Transparent && (!pen.bgSet || !colorEqual(pen.bg,desiredBg)) {
				if p,_:=sgrColorParams(desiredBg,false,mode,prof); p!="" { params=append(params,p); pen.bg=desiredBg; pen.bgSet=true }
			}
			if len(params)>0 { fmt.Fprintf(buf,"\x1b[%sm",strings.Join(params,";")) }
			buf.WriteRune(cell.Ch)
			x+=w
		}
		buf.WriteString("\x1b[0m")
		pen=penState{}
		if o.Relative {
			if y<canv.H-1 { fmt.Fprintf(buf,"\x1b[%dD\x1bD",canv.W) } else { fmt.Fprintf(buf,"\x1bD\x1b[%dD",canv.W) }
		} else { buf.WriteByte('\n') }
	}
}

func printCellColors2(buf *bytes.Buffer, cell Cell, cc *canvasConfig, pen *penState) {
	// Colours in mode 2 are the default fg/bg pair in some order.
	// Index 1 = default fg colour, 0 = default bg colour (see quantize).
	// Reverse video is needed when fg is the bg colour and bg is the fg colour.
	wantReverse:=false
	if !cell.Fg.Transparent && !cell.Bg.Transparent {
		if cell.Fg.Index==0 && cell.Bg.Index==1 { wantReverse=true }
	} else if cell.Ch==' ' && !cell.Bg.Transparent && cell.Bg.Index==1 {
		wantReverse=true
	}
	if wantReverse && !pen.reverse { buf.WriteString("\x1b[7m"); pen.reverse=true }
	if !wantReverse && pen.reverse { buf.WriteString("\x1b[0m"); pen.reverse=false }
}

func printSymbolCanvasOpt0(buf *bytes.Buffer, canv *Canvas, cc *canvasConfig, hoffset int) {
	o:=cc.Opts; prof:=cc.Profile; mode:=cc.Colors
	if hoffset>4096{hoffset=4096}
