{"command":"cat > print_pixel.go << 'EOF'
package main

import (
	"bytes"
	"encoding/base64"
	"encoding/binary"
	"fmt"
	"math"
	"sort"
	"strings"
)

func printKitty(buf *bytes.Buffer, canv *Canvas, cc *canvasConfig) {
	p:=canv.Pix
	raw:=make([]byte,p.W*p.H*4)
	for i,c:=range p.Pix { raw[i*4]=c.R; raw[i*4+1]=c.G; raw[i*4+2]=c.B; raw[i*4+3]=c.A }
	enc:=base64.StdEncoding.EncodeToString(raw)
	var out bytes.Buffer
	fmt.Fprintf(&out,"\x1b_Ga=T,f=32,s=%d,v=%d,c=%d,r=%d,m=1,q=2\x1b\\",p.W,p.H,canv.PixCols,canv.PixRows)
	chunkSize:=680
	for i:=0;i<len(enc);i+=chunkSize {
		end:=i+chunkSize; if end>len(enc){end=len(enc)}
		fmt.Fprintf(&out,"\x1b_Gm=1;%s\x1b\\",enc[i:end])
	}
	if len(enc)==0 { out.WriteString("\x1b_Gm=1;\x1b\\") }
	out.WriteString("\x1b_Gm=0\x1b\\")
	writePassthrough(buf,out.Bytes(),cc)
}

func tiffBytes(p *Frame) []byte {
	// Single-strip uncompressed little-endian TIFF, layout matching the reference.
	strip:=make([]byte,p.W*p.H*4)
	for i,c:=range p.Pix { strip[i*4]=c.R;strip[i*4+1]=c.G;strip[i*4+2]=c.B;strip[i*4+3]=c.A }
	ifdOff:=8+len(strip)
	type ent struct{tag,typ uint16; count uint32; val uint32}
	bpsOff:=ifdOff+2+11*12+4
	ents:=[]ent{
		{256,4,1,uint32(p.W)},{257,4,1,uint32(p.H)},{258,3,4,uint32(bpsOff)},{262,3,1,2},{273,4,1,8},{274,3,1,1},{277,3,1,4},{278,4,1,uint32(p.H)},{279,4,1,uint32(len(strip))},{284,3,1,1},{338,3,1,2},
	}
	var b bytes.Buffer; le:=binary.LittleEndian
	b.WriteString("II"); _=binary.Write(&b,le,uint16(42)); _=binary.Write(&b,le,uint32(ifdOff)); b.Write(strip)
	_=binary.Write(&b,le,uint16(len(ents)))
	for _,e:=range ents { _=binary.Write(&b,le,e.tag);_=binary.Write(&b,le,e.typ);_=binary.Write(&b,le,e.count);_=binary.Write(&b,le,e.val) }
	_=binary.Write(&b,le,uint32(0))
	for i:=0;i<4;i++{_ =binary.Write(&b,le,uint16(8))}
	return b.Bytes()
}

func printIterm(buf *bytes.Buffer, canv *Canvas, cc *canvasConfig) {
	data:=tiffBytes(canv.Pix)
	enc:=base64.StdEncoding.EncodeToString(data)
	var out bytes.Buffer
	fmt.Fprintf(&out,"\x1b]1337;File=inline=1;width=%d;height=%d;preserveAspectRatio=0:%s\a",canv.PixCols,canv.PixRows,enc)
	writePassthrough(buf,out.Bytes(),cc)
}

func writePassthrough(buf *bytes.Buffer, data []byte, cc *canvasConfig) {
	mode:=cc.Opts.Passthrough
	if mode=="auto" {
		// Resolve in main/profile before printing by setting Passthrough to concrete if needed; keep generic here.
		mode=resolvedPassthrough(cc)
	}
	switch mode {
	case "tmux":
		buf.WriteString("\x1bPtmux;")
		buf.Write(bytes.ReplaceAll(data,[]byte{0x1b},[]byte{0x1b,0x1b}))
		buf.WriteString("\x1b\\")
	case "screen":
		// GNU screen DCS passthrough, chunked at a modest size.
		chunk:=256
		for i:=0;i<len(data);i+=chunk { end:=i+chunk; if end>len(data){end=len(data)}; buf.WriteString("\x1bP"); buf.Write(data[i:end]); buf.WriteString("\x1b\\") }
	default:
		buf.Write(data)
	}
}
func resolvedPassthrough(cc *canvasConfig) string { return cc.PassthroughResolved }

// ---- Sixels ----

func sixelPercent(v uint8)int{ return int(v)*100/255 }

func (cc *canvasConfig) sixelPalette(p *Frame) (pal []RGBA, assign [][]int) {
	// assign[y][x] palette index, -1 transparent
	assign=make([][]int,p.H)
	for y:=range assign { assign[y]=make([]int,p.W); for x:=range assign[y]{assign[y][x]=-1} }
	// Build composited opaque pixel frame for assignment
	type pt struct{c RGBA; x,y int}
	var pts []pt
	comp:=make([]RGBA,len(p.Pix)); op:=make([]bool,len(p.Pix))
	for i,c:=range p.Pix { if !cc.isTransparentAlpha(c.A) { co:=composite(c,cc.BgDefault); comp[i]=co; op[i]=true; pts=append(pts,pt{co,i%p.W,i/p.W}) } }
	assignNearest:=func(palette []RGBA){
		// Apply dithering during assignment for sixels (separate from symbol dither).
		// Ordered/noise: perturb colour before nearest. Diffusion: propagate error.
		errBuf:=make([][3]float64,p.W*p.H)
		bayer:=[4][4]int{{0,8,2,10},{12,4,14,6},{3,11,1,9},{15,7,13,5}}
		dmode:=cc.Dither
		for y:=0;y<p.H;y++ { for x:=0;x<p.W;x++ { i:=y*p.W+x; if !op[i]{continue}
			cf:=[3]float64{float64(comp[i].R),float64(comp[i].G),float64(comp[i].B)}
			cf[0]+=errBuf[i][0];cf[1]+=errBuf[i][1];cf[2]+=errBuf[i][2]
			if dmode=="ordered" { off:=(float64(bayer[y%4][x%4])/16-0.5)*32*cc.Opts.DitherIntensity; cf[0]+=off;cf[1]+=off;cf[2]+=off }
			if dmode=="noise" { h:=uint32(x*374761393+y*668265263); h=(h^(h>>13))*1274126177; h^=h>>16; off:=(float64(h%1000)/1000-0.5)*32*cc.Opts.DitherIntensity; cf[0]+=off;cf[1]+=off;cf[2]+=off }
			ccolor:=RGBA{clamp255(int(math.Round(cf[0]))),clamp255(int(math.Round(cf[1]))),clamp255(int(math.Round(cf[2]))),255}
			best:=0; bd:=math.Inf(1); v:=rgbToVec(ccolor,cc.Opts.ColorSpace)
			for pi,pc:=range palette { d:=colorDist2(v,rgbToVec(pc,cc.Opts.ColorSpace)); if d<bd{bd=d;best=pi} }
			assign[y][x]=best
			if dmode=="diffusion" {
				pc:=palette[best]; er:=[3]float64{cf[0]-float64(pc.R),cf[1]-float64(pc.G),cf[2]-float64(pc.B)}
				type nb struct{dx,dy int;f float64}; for _,n:=range []nb{{1,0,7.0/16},{-1,1,3.0/16},{0,1,5.0/16},{1,1,1.0/16}} { nx,ny:=x+n.dx,y+n.dy; if nx>=0&&nx<p.W&&ny>=0&&ny<p.H { e:=&errBuf[ny*p.W+nx]; e[0]+=er[0]*n.f*cc.Opts.DitherIntensity;e[1]+=er[1]*n.f*cc.Opts.DitherIntensity;e[2]+=er[2]*n.f*cc.Opts.DitherIntensity } }
			}
		} }
	}
	switch cc.Colors {
	case ColorsNone,Colors2:
		pal=[]RGBA{cc.FgDefault,cc.BgDefault}; assignNearest(pal); return
	case Colors8:
		initPalette(); for i:=0;i<8;i++ { q:=palette256[i]; pal=append(pal,RGBA{uint8(q[0]),uint8(q[1]),uint8(q[2]),255}) }; assignNearest(pal); return
	case Colors16,Colors16_8:
		initPalette(); for i:=0;i<16;i++ { q:=palette256[i]; pal=append(pal,RGBA{uint8(q[0]),uint8(q[1]),uint8(q[2]),255}) }; assignNearest(pal); return
	case Colors240:
		initPalette(); for i:=16;i<256;i++ { q:=palette256[i]; pal=append(pal,RGBA{uint8(q[0]),uint8(q[1]),uint8(q[2]),255}) }; assignNearest(pal); return
	case Colors256:
		initPalette(); for i:=0;i<256;i++ { q:=palette256[i]; pal=append(pal,RGBA{uint8(q[0]),uint8(q[1]),uint8(q[2]),255}) }; assignNearest(pal); return
	default:
		pal=medianCutPalette(comp,op,256)
		assignNearest(pal)
		// Reference always emits one extra light-gray register after a generated palette.
		if len(pal)<256 { pal=append(pal,RGBA{238,238,238,255}) }
		return
	}
}

func medianCutPalette(comp []RGBA, op []bool, maxColors int) []RGBA {
	counts:=map[RGBA]int{}
	for i,c:=range comp { if op[i]{counts[c]++} }
	if len(counts)==0 { return []RGBA{{0,0,0,255}} }
	type ent struct{c RGBA;n int}
	type box struct{items []ent}
	var all []ent; for c,n:=range counts{all=append(all,ent{c,n})}
	boxes:=[]box{{all}}
	for len(boxes)<maxColors {
		// pick box with greatest range (then population)
		best:=-1; bestRange:=-1; bestPop:=-1; bestCh:=0
		for bi,b:=range boxes {
			if len(b.items)<2{continue}
			var mins,maxs [3]int; mins=[3]int{255,255,255}; pop:=0
			for _,e:=range b.items{pop+=e.n; vals:=[3]int{int(e.c.R),int(e.c.G),int(e.c.B)}; for ch:=0;ch<3;ch++{if vals[ch]<mins[ch]{mins[ch]=vals[ch]}; if vals[ch]>maxs[ch]{maxs[ch]=vals[ch]}}}
			rng:=0; chMax:=0; for ch:=0;ch<3;ch++{if maxs[ch]-mins[ch]>rng{rng=maxs[ch]-mins[ch];chMax=ch}}
			if rng>bestRange || (rng==bestRange&&pop>bestPop){best=bi;bestRange=rng;bestPop=pop;bestCh=chMax}
		}
		if best<0{break}
		b:=boxes[best]
		sort.Slice(b.items,func(i,j int)bool{ var vi,vj int; switch bestCh{case 0:vi,vj=int(b.items[i].c.R),int(b.items[j].c.R);case 1:vi,vj=int(b.items[i].c.G),int(b.items[j].c.G);default:vi,vj=int(b.items[i].c.B),int(b.items[j].c.B)}; if vi!=vj{return vi<vj}; return b.items[i].c.R<b.items[j].c.R })
		total:=0; for _,e:=range b.items{total+=e.n}
		acc:=0; split:=1; for i,e:=range b.items{acc+=e.n; if acc>=total/2 {split=i+1;break}}
		if split>=len(b.items){split=len(b.items)-1}; if split<1{split=1}
		left:=box{append([]ent{},b.items[:split]...)}; right:=box{append([]ent{},b.items[split:]...)}
		boxes=append(append(append([]box{},boxes[:best]...),left,right),boxes[best+1:]...)
	}
	var pal []RGBA
	for _,b:=range boxes {
		var sr,sg,sb,tot int; for _,e:=range b.items{sr+=int(e.c.R)*e.n;sg+=int(e.c.G)*e.n;sb+=int(e.c.B)*e.n;tot+=e.n}
		if tot==0{continue}; pal=append(pal,RGBA{uint8((sr+tot/2)/tot),uint8((sg+tot/2)/tot),uint8((sb+tot/2)/tot),255})
	}
	return pal
}

func printSixels(buf *bytes.Buffer, canv *Canvas, cc *canvasConfig) {
	p:=canv.Pix
	pal, assign := cc.sixelPalette(p)
	var out bytes.Buffer
	if cc.Profile.SixelInit!="" { out.WriteString(cc.Profile.SixelInit) }
	out.WriteString("\x1bP0;1;0q")
	fmt.Fprintf(&out,"\"1;1;%d;%d",p.W,p.H)
	np:=len(pal)
	// In 256-colour mode the reference emits definitions for #0..#254 only.
	if cc.Colors==Colors256 && np>255 { np=255 }
