	case Colors16,Colors16_8:
		initPalette(); for i:=0;i<16;i++ { q:=palette256[i]; pal=append(pal,RGBA{uint8(q[0]),uint8(q[1]),uint8(q[2]),255}) }; assignNearest(pal); return
	case Colors240:
		initPalette(); for i:=16;i<256;i++ { q:=palette256[i]; pal=append(pal,RGBA{uint8(q[0]),uint8(q[1]),uint8(q[2]),255}) }; assignNearest(pal); return
	case Colors256:
		initPalette(); for i:=0;i<256;i++ { q:=palette256[i]; pal=append(pal,RGBA{uint8(q[0]),uint8(q[1]),uint8(q[2]),255}) }; assignNearest(pal); return
	default:
		pal=medianCutPalette(comp,op,256)
		assignNearest(pal)
