		if len(pal)<256 { pal=append(pal,RGBA{238,238,238,255}) }
		return
	}
}

func medianCutPalette(comp []RGBA, op []bool, maxColors int) []RGBA {
	counts:=map[RGBA]int{}
	for i,c:=range comp { if op[i]{counts[c]++} }
	if len(counts)==0 { return []RGBA{{0,0,0,255}} }
	type ent struct{c RGBA;n int}
	type box struct{items []ent}
	var all []ent; for c,n:=range counts{all=append(all,ent{c,n})}
	boxes:=[]box{{all}}
	for len(boxes)<maxColors {
		// pick box with greatest range (then population)
		best:=-1; bestRange:=-1; bestPop:=-1; bestCh:=0
		for bi,b:=range boxes {
			if len(b.items)<2{continue}
			var mins,maxs [3]int; mins=[3]int{255,255,255}; pop:=0
			for _,e:=range b.items{pop+=e.n; vals:=[3]int{int(e.c.R),int(e.c.G),int(e.c.B)}; for ch:=0;ch<3;ch++{if vals[ch]<mins[ch]{mins[ch]=vals[ch]}; if vals[ch]>maxs[ch]{maxs[ch]=vals[ch]}}}
			rng:=0; chMax:=0; for ch:=0;ch<3;ch++{if maxs[ch]-mins[ch]>rng{rng=maxs[ch]-mins[ch];chMax=ch}}
			if rng>bestRange || (rng==bestRange&&pop>bestPop){best=bi;bestRange=rng;bestPop=pop;bestCh=chMax}
		}
		if best<0{break}
		b:=boxes[best]
		sort.Slice(b.items,func(i,j int)bool{ var vi,vj int; switch bestCh{case 0:vi,vj=int(b.items[i].c.R),int(b.items[j].c.R);case 1:vi,vj=int(b.items[i].c.G),int(b.items[j].c.G);default:vi,vj=int(b.items[i].c.B),int(b.items[j].c.B)}; if vi!=vj{return vi<vj}; return b.items[i].c.R<b.items[j].c.R })
		total:=0; for _,e:=range b.items{total+=e.n}
		acc:=0; split:=1; for i,e:=range b.items{acc+=e.n; if acc>=total/2 {split=i+1;break}}
		if split>=len(b.items){split=len(b.items)-1}; if split<1{split=1}
		left:=box{append([]ent{},b.items[:split]...)}; right:=box{append([]ent{},b.items[split:]...)}
		boxes=append(append(append([]box{},boxes[:best]...),left,right),boxes[best+1:]...)
	}
	var pal []RGBA
	for _,b:=range boxes {
		var sr,sg,sb,tot int; for _,e:=range b.items{sr+=int(e.c.R)*e.n;sg+=int(e.c.G)*e.n;sb+=int(e.c.B)*e.n;tot+=e.n}
		if tot==0{continue}; pal=append(pal,RGBA{uint8((sr+tot/2)/tot),uint8((sg+tot/2)/tot),uint8((sb+tot/2)/tot),255})
	}
	return pal
}

func printSixels(buf *bytes.Buffer, canv *Canvas, cc *canvasConfig) {
	p:=canv.Pix
	pal, assign := cc.sixelPalette(p)
	var out bytes.Buffer
	if cc.Profile.SixelInit!="" { out.WriteString(cc.Profile.SixelInit) }
	out.WriteString("\x1bP0;1;0q")
	fmt.Fprintf(&out,"\"1;1;%d;%d",p.W,p.H)
	np:=len(pal)
	// In 256-colour mode the reference emits definitions for #0..#254 only.
	if cc.Colors==Colors256 && np>255 { np=255 }
	for i:=0;i<np;i++ { c:=pal[i]; fmt.Fprintf(&out,"#%d;2;%d;%d;%d",i,sixelPercent(c.R),sixelPercent(c.G),sixelPercent(c.B)) }
	nbands:=(p.H+5)/6
	encodeRun:=func(ch byte, n int){
		for n>0 {
			if n>=3 { c:=n; if c>255{c=255}; fmt.Fprintf(&out,"!%d%c",c,ch); n-=c } else { for i:=0;i<n;i++{out.WriteByte(ch)}; n=0 }
		}
	}
	for band:=0;band<nbands;band++ {
		if band>0 { out.WriteByte('-') }
		y0:=band*6
		usedMap:=map[int]bool{}
		for y:=y0;y<y0+6&&y<p.H;y++{for x:=0;x<p.W;x++{if assign[y][x]>=0{usedMap[assign[y][x]]=true}}}
		var passes []int
		isFirst:=band==0; isLast:=band==nbands-1
		if isFirst||isLast||usedMap[0] { passes=append(passes,0) }
		var others []int; for i:=range usedMap{if i!=0{others=append(others,i)}}; sort.Ints(others); passes=append(passes,others...)
		if len(passes)==0 { continue }
		for pi,ci:=range passes {
			if pi>0 { out.WriteByte('$') }
			fmt.Fprintf(&out,"#%d",ci)
			// Build chars
			chars:=make([]byte,p.W)
			for x:=0;x<p.W;x++ { bits:=0; for j:=0;j<6;j++{y:=y0+j; if y<p.H&&assign[y][x]==ci{bits|=1<<uint(j)}}; chars[x]=byte(63+bits) }
			fullWidth := (ci==0 && (isFirst || len(usedMap)==0))
			end:=p.W
			if !fullWidth { for end>0 && chars[end-1]=='?' { end-- } }
			// RLE over chars[:end]
			for x:=0;x<end; { ch:=chars[x]; run:=1; for x+run<end&&chars[x+run]==ch{run++}; encodeRun(ch,run); x+=run }
		}
	}
	out.WriteString("\x1b\\")
	writePassthrough(buf,out.Bytes(),cc)
	_ = strings.Join
}
EOF"}

