	return old,true
}
func restoreTerm(fd uintptr, old [64]byte){ syscall.Syscall(syscall.SYS_IOCTL,fd,uintptr(0x5402),uintptr(unsafe.Pointer(&old[0]))) }

func fdReady(fd uintptr, timeout time.Duration) bool {
	var rfds syscall.FdSet
