				case 6: res.CellH=nums[1]; res.CellW=nums[2]
				}
			}
		case 'c':
			res.GotDA=true
			// params like ?62;4;... sixel attribute is 4 among parameters after ?
			for _,n:=range nums{if n==4{res.Sixel=true}}
		}
		i=j
	}
