	return res.GotDA
}
func splitInts(s string)[]int{ s=strings.TrimLeft(s,"?"); if s==""{return nil}; parts:=strings.Split(s,";"); var out []int; for _,p:=range parts{ if p==""{out=append(out,0)}else if v,err:=strconv.Atoi(p);err==nil{out=append(out,v)} }; return out }
func parseOSCRGB(s string)(RGBA,bool){
	s=strings.TrimSpace(s)
	if !strings.HasPrefix(strings.ToLower(s),"rgb:") { // maybe #rrggbb or a colour name
		return parseColor(s)
	}
	parts:=strings.Split(s[4:],"/"); if len(parts)<3{return RGBA{},false}
	var vals [3]uint8
	for i:=0;i<3;i++ { v,err:=strconv.ParseUint(parts[i],16,32); if err!=nil{return RGBA{},false}
