}
func fdSetZero(s *syscall.FdSet){ for i:=range s.Bits { s.Bits[i]=0 } }
func fdSetSet(s *syscall.FdSet, fd int){ s.Bits[fd/64] |= 1 << (uint(fd)%64) }

func runProbe(o *Options) probeResult {
