		if parseProbeData(data,&res) && res.GotDA { break }
	}
	parseProbeData(data,&res)
	return res
}

func parseProbeData(data []byte,res *probeResult) bool {
	s:=string(data)
	// OSC 10/11 ; rgb:.. terminated by BEL or ST
	for _,kind:=range []string{"10","11"} {
		idx:=strings.Index(s,"]"+kind+";")
		if idx>=0 {
			rest:=s[idx+len(kind)+2:]
			end:=strings.IndexAny(rest,"\a\x1b")
			if end>=0{rest=rest[:end]}
			if c,ok:=parseOSCRGB(rest); ok { if kind=="10"{cc:=c;res.Fg=&cc}else{cc:=c;res.Bg=&cc} }
		}
	}
	// CSI ... t and ... c : scan
	for i:=0;i+1<len(s);i++ {
		if s[i]!=0x1b||s[i+1]!='['{continue}
		j:=i+2; for j<len(s)&&!((s[j]>='A'&&s[j]<='Z')||(s[j]>='a'&&s[j]<='z')||s[j]=='~'){j++}
		if j>=len(s){break}
		final:=s[j]; params:=s[i+2:j]
		nums:=splitInts(params)
		switch final {
		case 't':
			if len(nums)>=3 {
				switch nums[0] {
				case 8: res.Rows=nums[1]; res.Cols=nums[2]
				case 4: res.WinPxH=nums[1]; res.WinPxW=nums[2]
				case 6: res.CellH=nums[1]; res.CellW=nums[2]
				}
			}
		case 'c':
			res.GotDA=true
			// params like ?62;4;... sixel attribute is 4 among parameters after ?
			for _,n:=range nums{if n==4{res.Sixel=true}}
		}
		i=j
	}
	if res.WinPxW>0&&res.Cols>0&&res.CellW==0{res.CellW=res.WinPxW/res.Cols}
	if res.WinPxH>0&&res.Rows>0&&res.CellH==0{res.CellH=res.WinPxH/res.Rows}
	return res.GotDA
}
func splitInts(s string)[]int{ s=strings.TrimLeft(s,"?"); if s==""{return nil}; parts:=strings.Split(s,";"); var out []int; for _,p:=range parts{ if p==""{out=append(out,0)}else if v,err:=strconv.Atoi(p);err==nil{out=append(out,v)} }; return out }
func parseOSCRGB(s string)(RGBA,bool){
	s=strings.TrimSpace(s)
	if !strings.HasPrefix(strings.ToLower(s),"rgb:") { // maybe #rrggbb or a colour name
		return parseColor(s)
	}
	parts:=strings.Split(s[4:],"/"); if len(parts)<3{return RGBA{},false}
	var vals [3]uint8
	for i:=0;i<3;i++ { v,err:=strconv.ParseUint(parts[i],16,32); if err!=nil{return RGBA{},false}
