func buildFileList(o *Options)([]string,bool){
	var entries []string
	stdinUsed:=false
	for _,fa:=range o.Files {
		var data []byte
		if fa.Path=="-" {
			stdinUsed=true
			b,_:=io.ReadAll(os.Stdin); data=b
		} else {
			b,err:=os.ReadFile(fa.Path); if err!=nil { continue }; data=b
		}
		if fa.Nul {
			for _,p:=range strings.Split(string(data),"\x00") { if p!="" { entries=append(entries,p) } }
		} else {
			// Lines: split on \n, strip trailing \r, skip empty lines.
			text:=string(data)
			for _,line:=range strings.Split(text,"\n") {
				line=strings.TrimSuffix(line,"\r")
				if line=="" { continue }
				entries=append(entries,line)
			}
		}
	}
	entries=append(entries,o.Positionals...)
	if len(o.Positionals)==0 && !stdinUsed { entries=append(entries,"-") }
	return entries,stdinUsed
