package main

import (
	"bytes"
	"fmt"
	"io"
	"math"
	"os"
	"path/filepath"
	"strings"
	"time"
)

func main(){
	progName="executable"
	if len(os.Args)>0 && os.Args[0]!="" { progName=os.Args[0] }
	initGlyphs()
	o:=parseArgs(os.Args[1:])
	if o.Help {
		fmt.Fprintf(os.Stdout, helpTemplate, progName)
		return
	}
	if o.Version {
		fmt.Fprint(os.Stdout, versionTemplate)
		return
	}
	// Post-parse validation in observed order.
	if stretchToInfinity(o) { fatalParse("Refusing to stretch images to infinity.") }
	if o.Work<1 || o.Work>9 { fatalParse("Work factor must be in the range [1-9].") }
	// Dash count
	dashCount:=0
	for _,p:=range o.Positionals{ if p=="-"{dashCount++} }
	for _,f:=range o.Files{ if f.Path=="-"{dashCount++} }
	if dashCount>1 { fatalParse("Dash '-' to pipe from standard input can be used at most once.") }
	if o.Watch {
		if len(o.Positionals)==0 && len(o.Files)==0 { fatalParse("Can only use --watch with a filename, not a pipe.") }
		if len(o.Files)>0 || len(o.Positionals)!=1 { fatalParse("Can only use --watch with exactly one file.") }
		if o.Positionals[0]=="-" { fatalParse("Can only use --watch with a filename, not a pipe.") }
	}
	if o.OptimizeSet && (o.Optimize<0||o.Optimize>9) { fatalParse("Optimization level %d is not in the range [0-9].",o.Optimize) }
	if o.Threads < -1 {
		// GLib critical assertion from the library; continue running.
		now:=time.Now().Format("15:04:05.000")
		fmt.Fprintf(os.Stderr,"\n** (%s:%d): CRITICAL **: %s: chafa_set_n_threads: assertion 'n >= -1' failed\n", filepath.Base(progName), os.Getpid(), now)
	}
	profile:=detectProfile()
	tg:=getTerminalGeom()
	probeRes:=runProbe(o)
	if probeRes.Cols>0||probeRes.Rows>0||probeRes.CellW>0||probeRes.CellH>0 { applyProbedSize(&tg,probeRes.Cols,probeRes.Rows,probeRes.CellW,probeRes.CellH) }
	// Re-check stretch-to-infinity if terminal size came from view/probe? Already handled for explicit view.
	format:=o.Format; if !o.FormatSet { format=profile.Format; if probeRes.Sixel && format==FormatSymbols && profile.Name!="safe" && os.Getenv("TERM")!="" {
		// Some terminals only gain sixel support via probe; keep conservative: do not switch unless profile is a known sixel-capable generic?
	} }
	colors:=o.Colors; if !o.ColorsSet { colors=profile.Colors }
	if !o.OptimizeSet { if colors==ColorsNone { o.Optimize=0 } else { o.Optimize=5 } }
	// Default fg/bg
	fgDefault:=RGBA{255,255,255,255}; bgDefault:=RGBA{0,0,0,255}
	if probeRes.Fg!=nil { fgDefault=*probeRes.Fg }
	if probeRes.Bg!=nil { bgDefault=*probeRes.Bg }
	if o.FgSet { fgDefault=o.Fg }
	if o.BgSet { bgDefault=o.Bg }
	if o.Invert { fgDefault,bgDefault=bgDefault,fgDefault }
	// Symbols
	symSet:=newSymbolSet()
	for _,t:=range profile.DefaultTags { symSet.addTag(t) }
	symSet.applySelectors(o.SymbolSelectors)
	fillSet:=newSymbolSet(); fillSet.clear()
	if len(o.FillSelectors)>0 { // applySelectors always adds space; remove it for fill if it wasn't selected? Space fill is meaningful only if selected.
		tmp:=newSymbolSet(); tmp.applySelectors(o.FillSelectors); fillSet=tmp
	}
	preprocess:=false
	if o.Preprocess==TriOn { preprocess=true } else if o.Preprocess==TriAuto { preprocess = colors==ColorsNone||colors==Colors2||colors==Colors8||colors==Colors16_8||colors==Colors16 }
	dither:=o.Dither
	if dither=="" { if format==FormatSixels { dither="noise" } else { dither="none" } }
	passthroughResolved:=o.Passthrough
	if passthroughResolved=="auto" {
		if os.Getenv("TMUX")!="" { passthroughResolved="tmux" } else if os.Getenv("STY")!="" { passthroughResolved="screen" } else if strings.HasPrefix(strings.ToLower(os.Getenv("TERM")),"screen") && (format==FormatKitty||format==FormatIterm||format==FormatSixels) {
			// In a plain GNU screen session, passthrough is needed; tmux also uses TERM=screen but TMUX env handled above.
			passthroughResolved="screen"
		} else { passthroughResolved="none" }
	}
	cc:=&canvasConfig{Opts:o,Profile:profile,Format:format,Colors:colors,Symbols:symSet.glyphs(),FillSymbols:fillSet.glyphs(),FgDefault:fgDefault,BgDefault:bgDefault,Preprocess:preprocess,Dither:dither,PassthroughResolved:passthroughResolved}
	// Build file list
	entries, stdinUsedForFiles := buildFileList(o)
	_ = stdinUsedForFiles
	// Cursor hide/show
	hideCursor:=profile.Detected && profile.CursorSeq && !o.Polite && !(format==FormatSymbols && colors==ColorsNone)
	out:=os.Stdout
	if hideCursor { _,_ = out.WriteString("\x1b[?25l") }
	exitCode:=0
	if o.GridSet || o.GridFlag {
		exitCode=runGrid(out,o,cc,tg,entries)
	} else {
		success:=0; failures:=0
		for idx, name := range entries {
			img, errStr := loadEntry(name)
			if errStr!="" {
				fmt.Fprintf(os.Stderr,"%s: Failed to open '%s': %s\n",progName,name,errStr)
				failures++
				continue
			}
			// Separator before a successful file that is not the first entry, unless clearing.
			if idx>0 && !o.Clear { _,_ = out.WriteString("\n") }
			if o.Clear && profile.ClearSeq!="" && profile.Detected { _,_ = out.WriteString(profile.ClearSeq) }
			displayImage(out,o,cc,tg,img,name, len(entries))
			success++
			if o.Watch {
				watchFile(out,o,cc,tg,name,len(entries))
			}
		}
		if failures>0 && success==0 && len(entries)>0 { exitCode=2 } else if failures>0 { exitCode=1 }
	}
	if hideCursor { _,_ = out.WriteString("\x1b[?25h") }
	if exitCode!=0 { os.Exit(exitCode) }
}

func buildFileList(o *Options)([]string,bool){
	var entries []string
	stdinUsed:=false
	for _,fa:=range o.Files {
		var data []byte
		if fa.Path=="-" {
			stdinUsed=true
			b,_:=io.ReadAll(os.Stdin); data=b
		} else {
			b,err:=os.ReadFile(fa.Path); if err!=nil { continue }; data=b
		}
		if fa.Nul {
			for _,p:=range strings.Split(string(data),"\x00") { if p!="" { entries=append(entries,p) } }
		} else {
			// Lines: split on \n, strip trailing \r, skip empty lines.
			text:=string(data)
			for _,line:=range strings.Split(text,"\n") {
				line=strings.TrimSuffix(line,"\r")
				if line=="" { continue }
				entries=append(entries,line)
			}
		}
	}
	entries=append(entries,o.Positionals...)
	if len(o.Positionals)==0 && !stdinUsed { entries=append(entries,"-") }
	return entries,stdinUsed
}

func loadEntry(name string)(*LoadedImage,string){
	if name=="-" {
		data,err:=io.ReadAll(os.Stdin)
		if err!=nil || len(data)==0 { return nil,"Could not cache input stream" }
		img,err:=loadImageFromBytes(data); if err!=nil { return nil,"Unknown file format" }
		return img,""
	}
	return loadImageFile(name)
}

func alignOffsets(o *Options,tg termGeom,cols,rows int)(int,int){
	viewW:=tg.ViewW; viewH:=tg.ViewH
	if o.ViewSet { viewW=o.ViewW; if viewW<0{viewW=viewInfinity}; viewH=o.ViewH; if viewH<0{viewH=viewInfinity} }
	effW:=viewW-o.MarginRight; effH:=viewH-o.MarginBottom
	xoff,yoff:=0,0
	if o.AlignH==0 { xoff=(effW-cols)/2 } else if o.AlignH>0 { xoff=effW-cols }
	if o.AlignV==0 { yoff=(effH-rows)/2 } else if o.AlignV>0 { yoff=effH-rows }
	if xoff<0{xoff=0}; if yoff<0{yoff=0}
	return xoff,yoff
}

func makeCanvasForFrame(o *Options,cc *canvasConfig,tg termGeom,fr *Frame)(*Canvas,int,int){
	cols,rows:=canvasSize(o,tg,fr.W,fr.H,cc.Format)
	if cc.Format==FormatSymbols {
		return cc.makeSymbolCanvas(fr,cols,rows),cols,rows
	}
	paintExact:=false
	if o.Exact==TriOn { paintExact=true } else if o.Exact==TriAuto {
		// Observed: paint unscaled when no explicit size and not zooming to fill, and the
		// pixel canvas can hold the source; also when canvas cells == source pixel dims (tiny images).
		cellW:=tg.CellPxW; if cellW<=0{cellW=10}; cellH:=tg.CellPxH; if cellH<=0{cellH=20}
		if !o.SizeSet && !o.ScaleMax && !o.Stretch && !o.FitWidth && cols*cellW>=fr.W && rows*cellH>=fr.H { paintExact=true }
		if cols==fr.W && rows==fr.H { paintExact=true }
		if fr.W<=1 || fr.H<=1 { if cols*cellW>=fr.W && rows*cellH>=fr.H && o.SizeSet && !o.ScaleMax && !o.Stretch { /* tiny-height cases are handled by the cells==src check above mostly */ } }
	}
	return cc.makePixelCanvas(fr,cols,rows,tg,paintExact),cols,rows
}

func writeCanvas(out io.Writer,o *Options,cc *canvasConfig,tg termGeom,canv *Canvas,xoff int, suppressFinalNewline bool){
	var buf bytes.Buffer
	switch cc.Format {
	case FormatSymbols:
		printSymbolCanvas(&buf,canv,cc,xoff)
	case FormatKitty:
		if xoff>0 { buf.WriteString(strings.Repeat(" ",minInt(xoff,4096))) }
		printKitty(&buf,canv,cc)
	case FormatIterm:
		if xoff>0 { buf.WriteString(strings.Repeat(" ",minInt(xoff,4096))) }
		printIterm(&buf,canv,cc)
	case FormatSixels:
		if xoff>0 { buf.WriteString(strings.Repeat(" ",minInt(xoff,4096))) }
		printSixels(&buf,canv,cc)
	}
	data:=buf.Bytes()
	if suppressFinalNewline {
		// For animation frames before the last, the symbol printer's final row newline is removed
		// (cursor restore follows). Pixel formats have no trailing newline in their payload here.
		if cc.Format==FormatSymbols && !o.Relative {
			if len(data)>0 && data[len(data)-1]=='\n' { data=data[:len(data)-1] }
		}
		_,_ = out.Write(data)
		return
	}
	_,_ = out.Write(data)
	if cc.Format!=FormatSymbols {
		if o.Relative {
			// Move below the image: index down then left, mirroring symbol relative ending (approximate).
			_,_ = out.WriteString("\x1bD")
		} else {
			_,_ = out.WriteString("\n")
		}
	}
}

func labelText(o *Options,cc *canvasConfig,tg termGeom,name string) string {
	if !o.Label { return "" }
	base:=name
	if name!="-" { base=filepath.Base(name) }
	viewW:=tg.ViewW; if o.ViewSet { viewW=o.ViewW; if viewW<0{viewW=viewInfinity} }
	effW:=viewW-o.MarginRight; if effW<0{effW=0}
	text:=base
	// Link handling
	linkOn:=false
	if o.Link==TriOn { linkOn=true } else if o.Link==TriAuto && cc.Profile.Hyperlink { linkOn=true }
	var line string
	if linkOn {
		abs:=name
		if name!="-" { if a,err:=filepath.Abs(name);err==nil{abs=a} }
		host,_:=os.Hostname()
		url:="file://"+host+abs
		if cc.Profile.Detected && cc.Profile.Hyperlink {
			line="\x1b]8;;"+url+"\x1b\\"+text+"\x1b]8;;\x1b\\"
		} else {
			// Safe terminals print the URL literally (observed reference behaviour).
			line=url+text
		}
	} else { line=text }
	// Pad visible width to effective view width (approximation; cap padding).
	vis:=len([]rune(text)); if linkOn && !(cc.Profile.Detected&&cc.Profile.Hyperlink) { vis=len([]rune(line)) }
	if effW>vis { pad:=effW-vis; if pad>4096{pad=4096}; line+=strings.Repeat(" ",pad) }
	return line+"\n"
}

func displayImage(out io.Writer,o *Options,cc *canvasConfig,tg termGeom,img *LoadedImage,name string,totalFiles int){
	if len(img.Frames)==0 { return }
	animated:=len(img.Frames)>1 && o.Animate
	if !animated {
		canv,cols,rows:=makeCanvasForFrame(o,cc,tg,img.Frames[0])
		xoff,yoff:=alignOffsets(o,tg,cols,rows)
		for i:=0;i<yoff;i++ { _,_=out.WriteString("\n") }
		writeCanvas(out,o,cc,tg,canv,xoff,false)
		if o.Label { _,_=out.WriteString(labelText(o,cc,tg,name)) }
		// Still-image duration wait
		if o.DurationSet && o.Duration>0 && !o.Watch { sleepInterruptible(o.Duration) }
		return
	}
	// Animation
	effDuration:=0.0
	if o.DurationSet { effDuration=o.Duration } else if totalFiles==1 { effDuration=math.Inf(1) }
	// Reserve space and save cursor (sequences depend on profile; safe profile emits only index downs).
	_,cols,rows:=makeCanvasForFrame(o,cc,tg,img.Frames[0])
	xoff,yoff:=alignOffsets(o,tg,cols,rows)
	for i:=0;i<yoff;i++ { _,_=out.WriteString("\n") }
	detected:=cc.Profile.Detected
	for i:=0;i<rows;i++ { _,_=out.WriteString("\x1bD") }
	if detected && !o.Polite {
		if rows>0 { fmt.Fprintf(out,"\x1b[%dA",rows) }
		_,_=out.WriteString("\x1b[s")
	}
	start:=time.Now()
	loopsDone:=0
	// GIF loop count: 0=infinite, -1=once, >0=number of additional loops (?) Go: LoopCount values as in gif spec.
	maxLoops:=0 // 0 means unbounded subject to duration
	if img.LoopCount>=0 { if img.LoopCount==0 { maxLoops=0 } else { maxLoops=img.LoopCount+1 } } else { maxLoops=1 }
	playedOnce:=false
	for {
		for fi,fr:=range img.Frames {
			canv, _, _ := makeCanvasForFrame(o,cc,tg,fr)
			isLastFrameOfPlay:=fi==len(img.Frames)-1
			// Determine if there will be another frame after this without knowing future loop termination precisely:
			// Suppress final newline for all frames except the very end is handled by a final newline after loop.
			writeCanvas(out,o,cc,tg,canv,xoff,true)
			// Frame delay
			delay:=frameDelay(o,fr)
			if delay>0 { time.Sleep(delay) }
			if !isLastFrameOfPlay || willLoopAgain(img,maxLoops,loopsDone,effDuration,start) {
				if detected && !o.Polite { _,_=out.WriteString("\x1b[u") }
			}
			if isLastFrameOfPlay { playedOnce=true }
			// Check duration after a full (?) frame; original checks at frame boundaries.
			if playedOnce && isLastFrameOfPlay {
				// handled by loop condition below
			}
		}
		loopsDone++
		if maxLoops>0 && loopsDone>=maxLoops { break }
		if !math.IsInf(effDuration,1) {
			if effDuration==0 { break }
			if time.Since(start).Seconds()>=effDuration { break }
			// continue looping; also if next loop would start after duration, original still stops at loop boundary.
			if detected && !o.Polite { /* cursor already restored after last frame if will loop */ }
		}
		if math.IsInf(effDuration,1) && maxLoops>0 && loopsDone>=maxLoops { break }
	}
	_,_=out.WriteString("\n")
	if o.Label { _,_=out.WriteString(labelText(o,cc,tg,name)) }
	// If a finite duration remains after a finite animation, hold.
	if o.DurationSet && !math.IsInf(effDuration,1) && effDuration>0 {
		rem:=effDuration-time.Since(start).Seconds(); if rem>0 { sleepInterruptible(rem) }
	}
}
func willLoopAgain(img *LoadedImage,maxLoops,loopsDone int,effDuration float64,start time.Time)bool{
	if maxLoops>0 && loopsDone+1>=maxLoops { return false }
	if !math.IsInf(effDuration,1) && effDuration==0 { return false }
	if !math.IsInf(effDuration,1) && time.Since(start).Seconds()>=effDuration { return false }
	return true
}
func frameDelay(o *Options,fr *Frame) time.Duration {
	if o.SpeedMax { return 0 }
	ms:=float64(fr.DelayMS)
	if o.SpeedFPS {
		if o.Speed>0 { return time.Duration(float64(time.Second)/o.Speed) }
		return 0
	}
	if o.SpeedSet && o.Speed>0 && !math.IsInf(o.Speed,1) { ms/=o.Speed } else if math.IsInf(o.Speed,1) { return 0 }
	if ms<0{ms=0}
	return time.Duration(ms*float64(time.Millisecond))
}
func sleepInterruptible(seconds float64){
	if math.IsInf(seconds,1) { select{} }
	time.Sleep(time.Duration(seconds*float64(time.Second)))
}

func watchFile(out io.Writer,o *Options,cc *canvasConfig,tg termGeom,name string,totalFiles int){
	// The reference exits promptly in non-interactive use unless a duration
	// keeps it around; implement polling when stdout is a tty or a duration is set.
	if o.DurationSet && o.Duration==0 { return }
	info,err:=os.Stat(name); if err!=nil{return}
	lastMod:=info.ModTime(); lastSize:=info.Size()
	start:=time.Now(); deadlineSet:=o.DurationSet && !math.IsInf(o.Duration,1) && o.Duration>0
	// If not a tty and no duration, original returns immediately in our probes.
	if !isTTY(os.Stdout) && !deadlineSet { return }
	for {
		if deadlineSet && time.Since(start).Seconds()>=o.Duration { return }
		time.Sleep(100*time.Millisecond)
		info,err:=os.Stat(name); if err!=nil{continue}
		if !info.ModTime().Equal(lastMod)||info.Size()!=lastSize {
			lastMod=info.ModTime(); lastSize=info.Size()
			// Small settle delay
			time.Sleep(20*time.Millisecond)
			img,errStr:=loadImageFile(name); if errStr!=""{continue}
			if o.Clear && cc.Profile.ClearSeq!="" && cc.Profile.Detected { _,_=out.WriteString(cc.Profile.ClearSeq) }
			displayImageNoWait(out,o,cc,tg,img,name)
		}
	}
}
func displayImageNoWait(out io.Writer,o *Options,cc *canvasConfig,tg termGeom,img *LoadedImage,name string){
	if len(img.Frames)==0{return}
	canv,cols,rows:=makeCanvasForFrame(o,cc,tg,img.Frames[0])
	xoff,yoff:=alignOffsets(o,tg,cols,rows); for i:=0;i<yoff;i++{_,_=out.WriteString("\n")}
	writeCanvas(out,o,cc,tg,canv,xoff,false)
	if o.Label{_,_=out.WriteString(labelText(o,cc,tg,name))}
}

func runGrid(out io.Writer,o *Options,cc *canvasConfig,tg termGeom,entries []string) int {
	// Minimal grid implementation: fall back to sequential display for now,
	// preserving error handling/exit codes. A full grid layout is added in grid.go.
	return runGridLayout(out,o,cc,tg,entries)
}
