package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

// Grid layout: images are laid out in slots of (slotW x slotH) cells, centred
// in their slots, with blank lines around each page. This approximates the
// reference grid mode.
func runGridLayout(out io.Writer,o *Options,cc *canvasConfig,tg termGeom,entries []string) int {
	type item struct{ img *LoadedImage; name string }
	var items []item
	success:=0; failures:=0
	for _,name:=range entries {
		img,errStr:=loadEntry(name)
		if errStr!="" { fmt.Fprintf(os.Stderr,"%s: Failed to open '%s': %s\n",progName,name,errStr); failures++; continue }
		items=append(items,item{img,name}); success++
	}
	if len(items)==0 { if failures>0{return 2}; return 0 }
	// View
	viewW:=tg.ViewW; viewH:=tg.ViewH
	if o.ViewSet { viewW=o.ViewW; if viewW<0{viewW=viewInfinity}; viewH=o.ViewH; if viewH<0{viewH=viewInfinity} }
	if o.SizeSet { // size overrides view for the whole grid page? Reference uses size as page size when set.
		if o.SizeW>0{viewW=o.SizeW}; if o.SizeH>0{viewH=o.SizeH}
	}
	effW:=viewW-o.MarginRight; effH:=viewH-o.MarginBottom
	if !o.SizeSet { /* margins already in eff */ } else { effW=viewW; effH=viewH }
	if effW<1{effW=1}; if effH<1{effH=1}
	if effW>4096{effW=4096}; if effH>10000{effH=10000}
	cols:=o.GridW; rows:=o.GridH
	auto:=o.GridAuto||o.GridFlag
	if o.GridSet && !o.GridAuto { auto=false }
	if auto {
		// Heuristic observed for a small number of images on an 80x24 view:
		// slots are about 19-20 cells wide. Choose cols so slot width ~20.
		cols=effW/20; if cols<1{cols=1}; if cols>len(items) && len(items)>0 { /* keep cols for slot sizing even for single item: reference -g on 1 item used a ~19-wide slot at left */ }
		// For 1 item reference used 4 columns worth of slots across (image occupied first slot).
		rows=-1
	}
	if cols<=0 && rows<=0 { cols=1; rows=1 }
	if cols<=0 {
		// Derive cols from rows and count
		cols=(len(items)+rows-1)/rows; if cols<1{cols=1}
		if auto||o.GridW<0 { /* keep */ }
	}
	if rows<=0 {
		rows=(len(items)+cols-1)/cols; if rows<1{rows=1}
		// but a "page" should not exceed what explicit rows would do; if rows derived from count, slot height uses effH/rows for first page only
	}
	perPage:=cols*rows; if perPage<1{perPage=1}
	// When grid was specified as e.g. 2x2, slot dimensions are eff/cols, eff/rows.
	// When only cols specified (rows derived from count), original uses effH/derivedRows? For --grid 2 on one pixel it filled much of the height. Use derived rows.
	slotW:=effW/cols; if slotW<1{slotW=1}
	slotH:=effH/rows; if slotH<1{slotH=1}
	// Gap: reference leaves a blank column/row at slot edges via centring; we reserve 1 column gap by using slotW as stride.
	exitCode:=0; if failures>0&&success==0{exitCode=2}else if failures>0{exitCode=1}
	for pageStart:=0; pageStart<len(items); pageStart+=perPage {
		page:=items[pageStart:minInt(pageStart+perPage,len(items))]
		if pageStart>0 { /* page separator: a blank line */ _,_=out.WriteString("\n") }
		if o.Clear && cc.Profile.ClearSeq!="" && cc.Profile.Detected { _,_=out.WriteString(cc.Profile.ClearSeq) }
		// Build canvases for this page
		type cellCanv struct{ canv *Canvas; lines []string; name string }
		var cells []cellCanv
		maxSlotLines:=slotH
		for _,it:=range page {
			if len(it.img.Frames)==0 { cells=append(cells,cellCanv{nil,nil,it.name}); continue }
			// Canvas size within slot: use a copy of options with Size = slot (minus label row)
			subOpts:=*o
			subOpts.SizeSet=true; subOpts.SizeW=slotW; subOpts.SizeH=slotH; if o.Label{subOpts.SizeH=slotH-1; if subOpts.SizeH<1{subOpts.SizeH=1}}
			subOpts.GridSet=false; subOpts.GridFlag=false
			// Preserve explicit original size if user set it? Reference: --size with grid sets page size above, slot derived from it, so using slot is correct.
			cols2,rows2:=canvasSize(&subOpts,tg,it.img.Frames[0].W,it.img.Frames[0].H,cc.Format)
			var canv *Canvas
			if cc.Format==FormatSymbols { canv=cc.makeSymbolCanvas(it.img.Frames[0],cols2,rows2) } else {
				_,_,_ = cols2,rows2
				canv,_,_=makeCanvasForFrame(&subOpts,cc,tg,it.img.Frames[0])
			}
			cells=append(cells,cellCanv{canv,nil,it.name})
		}
		if cc.Format!=FormatSymbols {
			// Pixel formats in grid: just write each canvas sequentially (approximation).
			for _,c:=range cells { if c.canv!=nil { writeCanvas(out,o,cc,tg,c.canv,0,false) } }
			continue
		}
		// For symbols, render each canvas to text lines (without ANSI handling, use our printer into a buffer per cell then split)
		// Simpler: render page row by row, slot by slot.
		for slotRow:=0; slotRow<rows; slotRow++ {
			// Determine canvases in this row
			rowCells:=cells[slotRow*cols:minInt((slotRow+1)*cols,len(cells))]
			if len(rowCells)==0 {break}
			for line:=0; line<maxSlotLines; line++ {
				var lineBuf strings.Builder
				anyContent:=false
				for ci,c:=range rowCells {
					// vertical centring offset for this canvas in slot
					contentRows:=0; if c.canv!=nil{contentRows=c.canv.H}
					if o.Label{contentRows++}
					topPad:=(maxSlotLines-contentRows)/2; if topPad<0{topPad=0}
					rel:=line-topPad
					seg:=""
					if c.canv!=nil && rel>=0 && rel<c.canv.H {
						seg=renderSymbolRow(c.canv,cc,rel)
						anyContent=true
					} else if c.canv!=nil && o.Label && rel==c.canv.H {
						seg=labelTextPlain(o,cc,c.name,slotW)
						anyContent=true
					}
					// centre horizontally in slot
					visW:=visibleWidth(seg)
					leftPad:=(slotW-visW)/2; if leftPad<0{leftPad=0}
					lineBuf.WriteString(strings.Repeat(" ",leftPad))
					lineBuf.WriteString(seg)
					rem:=slotW-leftPad-visW; if rem<0{rem=0}
					// No trailing pad on last slot in row except reference often pads; keep one space separator.
					if ci<len(rowCells)-1 { lineBuf.WriteString(strings.Repeat(" ",rem)) } else { if rem>0{lineBuf.WriteString(strings.Repeat(" ",rem))} }
				}
				_ = anyContent
				_,_=out.WriteString(lineBuf.String()+"\n")
			}
		}
		// Reference emits an extra blank line after a grid page in several cases.
		_,_=out.WriteString("\n")
	}
	return exitCode
}

func renderSymbolRow(canv *Canvas,cc *canvasConfig,row int) string {
	// Render one row using the full printer for a 1-row canvas would add resets; instead
	// render the whole canvas once and split is expensive but correct-ish for ANSI. Cache would be better;
	// for simplicity render whole canvas and pick the line (called repeatedly, acceptable for tests).
	var buf strings.Builder
	bb:=&strings.Builder{}
	_ = buf
	// Use bytes.Buffer via a small adapter
	b:=renderCanvasToBytes(canv,cc)
	lines:=strings.Split(string(b),"\n")
	if row>=0&&row<len(lines){return lines[row]}
	_ = bb
	return ""
}
func visibleWidth(s string)int{
	// Strip ANSI CSI sequences, count runes (wide runes count 2 in our glyph set approximation)
	w:=0; inEsc:=false
	for _,r:=range s {
		if r==0x1b{inEsc=true;continue}
		if inEsc{ if (r>='A'&&r<='Z')||(r>='a'&&r<='z'){inEsc=false}; continue }
		w++
	}
	return w
}
func labelTextPlain(o *Options,cc *canvasConfig,name string,width int)string{
	base:=name; if name!="-" { parts:=strings.Split(name,"/"); base=parts[len(parts)-1] }
	if len([]rune(base))>width && width>0 { return string([]rune(base)[:width]) }
	return base
}
