import subprocess,re,sys
def parse(out):
 # returns list rows cells (char,fg,bg) tracking SGR in full mode (38;2 /48;2 / reset / reverse)
 rows=[]; row=[]; fg=None;bg=None;rev=False; i=0; s=out.decode()
 while i<len(s):
  if s[i]=='\x1b':
   m=re.match(r'\x1b\[([0-9;]*)m',s[i:])
   if m:
    ps=m.group(1).split(';') if m.group(1) else []
    j=0
    if ps==['0'] or ps==[]: fg=None;bg=None;rev=False
    else:
     while j<len(ps):
      if ps[j]=='0': fg=None;bg=None;rev=False;j+=1
      elif ps[j]=='7':rev=True;j+=1
      elif ps[j]=='38' and j+4<len(ps): fg=tuple(map(int,ps[j+2:j+5]));j+=5
      elif ps[j]=='48' and j+4<len(ps): bg=tuple(map(int,ps[j+2:j+5]));j+=5
      elif ps[j]=='38' and j+2<len(ps): fg=('idx',int(ps[j+2]));j+=3
      elif ps[j]=='48' and j+2<len(ps): bg=('idx',int(ps[j+2]));j+=3
      else:j+=1
    i+=len(m.group(0));continue
   i+=1;continue
  if s[i]=='\n': rows.append(row);row=[];i+=1;continue
  # effective fg/bg if reverse: visual fg is previous bg (default black), bg=fg param. Represent as remarks
  row.append((s[i],fg,bg,rev));i+=1
 if row:rows.append(row)
 return rows
def run(exe,args):
 p=subprocess.run(["./executable"]+args,executable=exe,capture_output=True,env={"PATH":"x"});return parse(p.stdout)
