cat > glyphs_extra_init.go << 'EOF'
package main

import "unicode"

func tagsForExtraCP(cp rune) []string {
	var tags []string
	switch {
	case cp >= 0x2500 && cp <= 0x257F:
		tags = append(tags, "border")
		if cp == 0x2571 || cp == 0x2572 || cp == 0x2573 {
			tags = append(tags, "diagonal")
		}
	case cp == 0x25A0 || cp == 0x25AE:
		tags = append(tags, "geometric", "solid")
	case cp == 0x25B2 || cp == 0x25BC:
		tags = append(tags, "geometric", "wedge", "solid")
	case cp == 0x25CF:
		tags = append(tags, "geometric", "solid", "dot")
	case cp >= 0x2190 && cp <= 0x2193:
		tags = append(tags, "extra")
	case cp >= 0x23BA && cp <= 0x23BD:
		tags = append(tags, "technical", "extra")
	case cp >= 0x1FB00 && cp <= 0x1FBFF:
		tags = append(tags, "legacy")
		// Sextant block characters live at the start of the legacy block;
		// the remainder includes quadrant/terminal graphics and wedges.
		if cp <= 0x1FB3B {
			tags = append(tags, "sextant", "block")
		} else {
			tags = append(tags, "block", "quad", "wedge", "geometric")
		}
	default:
		// Letters and miscellaneous Latin/Greek symbols.
		if unicode.IsLetter(cp) {
			tags = append(tags, "alpha", "alnum")
			if cp <= 0x24F || (cp >= 0x1D00 && cp <= 0x1D7F) {
				tags = append(tags, "latin")
			}
		}
		if unicode.IsDigit(cp) {
			tags = append(tags, "digit", "alnum")
		}
		// Symbols outside the basic sets are treated as "extra" in the reference's
		// broad categories (affects the "extra" selector approximately).
		tags = append(tags, "extra")
	}
	return tags
}

func initExtraGlyphs() {
	for cp, bits := range extraGlyphBits {
		addGlyph(cp, bits, 1, tagsForExtraCP(cp)...)
	}
}
