package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

func runGridLayout(out io.Writer, o *Options, cc *canvasConfig, tg termGeom, entries []string) int {
	type item struct {
		img  *LoadedImage
		name string
	}
	var items []item
	success := 0
	failures := 0
	for _, name := range entries {
		img, errStr := loadEntry(name)
		if errStr != "" {
			fmt.Fprintf(os.Stderr, "%s: Failed to open '%s': %s\n", progName, name, errStr)
			failures++
			continue
		}
		items = append(items, item{img, name})
		success++
	}
	if len(items) == 0 {
		if failures > 0 {
			return 2
		}
		return 0
	}
	exitCode := 0
	if failures > 0 && success == 0 {
		exitCode = 2
	} else if failures > 0 {
		exitCode = 1
	}

	// Page size
	viewW := tg.ViewW
	viewH := tg.ViewH
	if o.ViewSet {
		viewW = o.ViewW
		if viewW < 0 {
			viewW = viewInfinity
		}
		viewH = o.ViewH
		if viewH < 0 {
			viewH = viewInfinity
		}
	}
	pageW := viewW - o.MarginRight
	pageH := viewH - o.MarginBottom
	if o.SizeSet {
		if o.SizeW > 0 {
			pageW = o.SizeW
		}
		if o.SizeH > 0 {
			pageH = o.SizeH
		}
	}
	if pageW < 1 {
		pageW = 1
	}
	if pageH < 1 {
		pageH = 1
	}
	fr := effectiveFontRatio(o, tg)

	// Grid geometry
	var cols, rowsPerPage, strideW, strideH int
	auto := o.GridAuto || o.GridFlag
	if o.GridSet && !o.GridAuto {
		auto = false
	}
	if auto {
		strideW = 20
		strideH = int(float64(strideW) * fr)
		if strideH < 1 {
			strideH = 1
		}
		cols = pageW / strideW
		if cols < 1 {
			cols = 1
		}
		rowsPerPage = pageH / strideH
		if rowsPerPage < 1 {
			rowsPerPage = 1
		}
	} else if o.GridW > 0 && o.GridH > 0 {
		cols = o.GridW
		rowsPerPage = o.GridH
		strideW = pageW / cols
		strideH = pageH / rowsPerPage
	} else if o.GridW > 0 {
		cols = o.GridW
		strideW = pageW / cols
		areaW := strideW - 1
		areaH := int(float64(areaW) * fr)
		if areaH < 1 {
			areaH = 1
		}
		strideH = areaH + 1
		rowsPerPage = pageH / strideH
		if rowsPerPage < 1 {
			rowsPerPage = 1
		}
	} else if o.GridH > 0 {
		rowsPerPage = o.GridH
		strideH = pageH / rowsPerPage
		targetStrideW := int(float64(strideH) / fr)
		if targetStrideW < 1 {
			targetStrideW = 1
		}
		cols = pageW / targetStrideW
		if cols < 1 {
			cols = 1
		}
		strideW = pageW / cols
	} else {
		cols = 1
		rowsPerPage = 1
		strideW = pageW
		strideH = pageH
	}
	if strideW < 2 {
		strideW = 2
	}
	if strideH < 2 {
		strideH = 2
	}
	areaW := strideW - 1
	areaH := strideH - 1
	perPage := cols * rowsPerPage
	if perPage < 1 {
		perPage = 1
	}

	alignH := 0
	if o.AlignHSet {
		alignH = o.AlignH
	}
	alignV := 1
	if o.AlignVSet {
		alignV = o.AlignV
	}

	for pageStart := 0; pageStart < len(items); pageStart += perPage {
		page := items[pageStart:minInt(pageStart+perPage, len(items))]
		if o.Clear && cc.Profile.ClearSeq != "" && cc.Profile.Detected {
			_, _ = io.WriteString(out, cc.Profile.ClearSeq)
		}
		// Grid rows within page
		for rowStart := 0; rowStart < len(page); rowStart += cols {
			rowItems := page[rowStart:minInt(rowStart+cols, len(page))]
			// Build canvases for slots in this row
			slotCanvases := make([]*Canvas, len(rowItems))
			slotCols := make([]int, len(rowItems))
			slotRows := make([]int, len(rowItems))
			for i, it := range rowItems {
				if len(it.img.Frames) == 0 {
					continue
				}
				framed := it.img.Frames[0]
				var c2, r2 int
				if cc.Format == FormatSymbols {
					if o.Exact == TriOn {
						c2, r2 = canvasSize(o, tg, framed.W, framed.H, cc.Format)
						if c2 > areaW {
							c2 = areaW
						}
						if r2 > areaH {
							r2 = areaH
						}
					} else if o.Stretch {
						c2, r2 = areaW, areaH
					} else {
						c2, r2 = calcFit(framed.W, framed.H, areaW, areaH, fr, true, false)
					}
					slotCanvases[i] = cc.makeSymbolCanvas(framed, c2, r2)
				} else {
					// Pixel formats: build a pixel canvas sized to the slot by using a sub-options with size=area
					sub := *o
					sub.SizeSet = true
					sub.SizeW = areaW
					sub.SizeH = areaH
					sub.ScaleMax = true
					canv, cc2, rr2 := makeCanvasForFrame(&sub, cc, tg, framed)
					slotCanvases[i] = canv
					c2, r2 = cc2, rr2
				}
				slotCols[i] = c2
				slotRows[i] = r2
			}
			if cc.Format != FormatSymbols {
				// Approximate pixel grid as sequential graphics (rare combination).
				for _, canv := range slotCanvases {
					if canv != nil {
						writeCanvas(out, o, cc, tg, canv, 0, false)
					}
				}
			} else {
				totalW := (len(rowItems)-1)*strideW + areaW
				comp := &Canvas{W: totalW, H: areaH, Cells: make([]Cell, totalW*areaH)}
				for i := range comp.Cells {
					comp.Cells[i] = Cell{Ch: ' ', Fg: CellColor{Transparent: true}, Bg: CellColor{Transparent: true}, Width: 1}
				}
				for i, canv := range slotCanvases {
					if canv == nil {
						continue
					}
					xoff := 0
					if alignH == 0 {
						xoff = (areaW - slotCols[i]) / 2
					} else if alignH > 0 {
						xoff = areaW - slotCols[i]
					}
					yoff := 0
					if alignV == 0 {
						yoff = (areaH - slotRows[i]) / 2
					} else if alignV > 0 {
						yoff = areaH - slotRows[i]
					}
					if xoff < 0 {
						xoff = 0
					}
					if yoff < 0 {
						yoff = 0
					}
					baseX := i*strideW + xoff
					for y := 0; y < canv.H && yoff+y < areaH; y++ {
						for x := 0; x < canv.W && baseX+x < totalW; x++ {
							comp.Cells[(yoff+y)*totalW+baseX+x] = canv.Cells[y*canv.W+x]
						}
					}
				}
				var buf bytes.Buffer
				printSymbolCanvas(&buf, comp, cc, 0)
				_, _ = out.Write(buf.Bytes())
			}
			if o.Label {
				var lb strings.Builder
				for _, it := range rowItems {
					base := it.name
					if base != "-" {
						base = filepath.Base(base)
					}
					lb.WriteString(centerField(base, strideW, o, cc, it.name))
				}
				_, _ = io.WriteString(out, lb.String()+"\n")
			}
			_, _ = io.WriteString(out, "\n")
		}
	}
	return exitCode
}

func centerField(text string, width int, o *Options, cc *canvasConfig, fullName string) string {
	vis := len([]rune(text))
	if vis > width {
		r := []rune(text)
		return string(r[:width])
	}
	left := (width - vis) / 2
	right := width - vis - left
	// Hyperlinks in grid labels follow the same rules as normal labels for the text part.
	if (o.Link == TriOn || (o.Link == TriAuto && cc.Profile.Hyperlink)) && fullName != "-" {
		abs := fullName
		if a, err := filepath.Abs(fullName); err == nil {
			abs = a
		}
		host, _ := osHostname()
		url := "file://" + host + abs
		if cc.Profile.Detected && cc.Profile.Hyperlink {
			return strings.Repeat(" ", left) + "\x1b]8;;" + url + "\x1b\\" + text + "\x1b]8;;\x1b\\" + strings.Repeat(" ", right)
		}
		s := url + text
		if len(s) > width {
			return s[:width]
		}
		return s + strings.Repeat(" ", width-len(s))
	}
	return strings.Repeat(" ", left) + text + strings.Repeat(" ", right)
}

func osHostname() (string, error) {
	return hostnameCached()
}
