			slotCanvases := make([]*Canvas, len(rowItems))
			slotCols := make([]int, len(rowItems))
			slotRows := make([]int, len(rowItems))
			for i, it := range rowItems {
				if len(it.img.Frames) == 0 {
					continue
				}
				framed := it.img.Frames[0]
				var c2, r2 int
				if cc.Format == FormatSymbols {
					if o.Exact == TriOn {
						c2, r2 = canvasSize(o, tg, framed.W, framed.H, cc.Format)
						if c2 > areaW {
							c2 = areaW
						}
						if r2 > areaH {
							r2 = areaH
						}
					} else if o.Stretch {
						c2, r2 = areaW, areaH
					} else {
