					sub := *o
					sub.SizeSet = true
					sub.SizeW = areaW
					sub.SizeH = areaH
					sub.ScaleMax = true
					canv, cc2, rr2 := makeCanvasForFrame(&sub, cc, tg, framed)
					slotCanvases[i] = canv
					c2, r2 = cc2, rr2
				}
				slotCols[i] = c2
				slotRows[i] = r2
			}
