				_, _ = io.WriteString(out, lb.String()+"\n")
			}
			_, _ = io.WriteString(out, "\n")
		}
	}
	return exitCode
}

func centerField(text string, width int, o *Options, cc *canvasConfig, fullName string) string {
	vis := len([]rune(text))
	if vis > width {
		r := []rune(text)
		return string(r[:width])
	}
	left := (width - vis) / 2
	right := width - vis - left
	// Hyperlinks in grid labels follow the same rules as normal labels for the text part.
	if (o.Link == TriOn || (o.Link == TriAuto && cc.Profile.Hyperlink)) && fullName != "-" {
