cat > glyphs_extra_init.go << 'EOF'
package main

import (
	"sort"
	"unicode"
)

var badGlyphs = map[rune]bool{
	0x25AA: true, 0x25B6: true, 0x25C0: true, 0x25C6: true,
	0x25E2: true, 0x25E3: true, 0x25E4: true, 0x25E5: true, 0x25FC: true,
}

func tagsForExtraCP(cp rune) []string {
	if badGlyphs[cp] {
		return []string{"bad", "ambiguous"}
	}
	var tags []string
	switch {
	case cp >= 0x2500 && cp <= 0x257F:
		tags = append(tags, "border")
		if cp == 0x2571 || cp == 0x2572 || cp == 0x2573 {
			tags = append(tags, "diagonal")
		}
		if (cp >= 0x2504 && cp <= 0x250B) || (cp >= 0x254C && cp <= 0x254F) || (cp >= 0x2574 && cp <= 0x257B) {
			tags = append(tags, "dot")
		}
	case cp == 0x25A0 || cp == 0x25AE:
		tags = append(tags, "geometric", "dot")
	case cp == 0x25B2 || cp == 0x25BC:
		tags = append(tags, "geometric", "wedge")
	case cp == 0x25CF:
		tags = append(tags, "geometric")
	case (cp >= 0x2190 && cp <= 0x2193) || (cp >= 0x23BA && cp <= 0x23BD):
		tags = append(tags, "technical")
	case cp >= 0x1FB00 && cp <= 0x1FBFF:
		tags = append(tags, "legacy")
		if cp <= 0x1FB3B {
			tags = append(tags, "sextant")
		}
		if (cp >= 0x1FB3C && cp <= 0x1FB6F) || cp == 0x1FB9A || cp == 0x1FB9B {
			tags = append(tags, "wedge")
		}
		if cp >= 0x1FB82 && cp <= 0x1FB8B {
			tags = append(tags, "inverted")
		}
	case cp == 0x039E:
		tags = append(tags, "alpha", "alnum", "extra")
	case cp == 0x00B7:
		tags = append(tags, "dot")
	default:
		if unicode.IsLetter(cp) {
			tags = append(tags, "alpha", "alnum")
			if cp <= 0x24F || (cp >= 0x1D00 && cp <= 0x1D7F) {
				tags = append(tags, "latin")
			}
		}
		if unicode.IsDigit(cp) {
			tags = append(tags, "digit", "alnum")
		}
	}
	return tags
}

func initExtraGlyphs() {
	cps := make([]rune, 0, len(extraGlyphBits))
	for cp := range extraGlyphBits {
		cps = append(cps, cp)
	}
	sort.Slice(cps, func(i, j int) bool { return cps[i] < cps[j] })
	for _, cp := range cps {
		addGlyph(cp, extraGlyphBits[cp], 1, tagsForExtraCP(cp)...)
		if badGlyphs[cp] {
			delete(glyphByCP[cp].Tags, "all")
		}
	}
}
