{"command":"cat > /tmp/fitgeom2.py << 'PY'
import ast,math
data=ast.literal_eval(open('/tmp/geomdata.txt').read())
def ceil(x):return max(1,math.ceil(x-1e-9))
def rnd(x):return max(1,math.floor(x+0.5))
def flr(x):return max(1,math.floor(x))
def calcfit(sw,sh,bw,bh,fr,zoom=True,roundmode='ceil'):
 asp=sw/sh
 if not zoom: bw=min(bw,sw);bh=min(bh,sh)
 rf={'ceil':ceil,'round':rnd,'floor':flr}[roundmode]
 hfw=rf(bw*fr/asp)
 if hfw<=bh:return(max(1,bw),max(1,hfw))
 return(max(1,rf(bh*asp/fr)),max(1,bh))
# View box effective is 80x24 in these tests (some outputs capped at 24 rows).
def predict(w,h,fr,scale,cellmode,mode,roundmode):
 B=10.0
 if cellmode=='short10': cw=B*max(1,fr);ch=B*max(1,1/fr)
 elif cellmode=='term': cw,ch=10,20
 elif cellmode=='area200': cw=math.sqrt(200*fr);ch=math.sqrt(200/fr)
 elif cellmode=='height20': ch=20;cw=20*fr
 elif cellmode=='width10': cw=10;ch=10/fr
 elif cellmode=='short20': cw=20*max(1,fr)/ (2 if fr<1 else 1);ch=20*max(1,1/fr)/(1 if fr<1 else 2)  # nonsense placeholder
 sw,sh=w*scale,h*scale
 rf={'ceil':ceil,'round':rnd,'floor':flr}[roundmode]
 if mode=='indep': cols,rows=rf(sw/cw),rf(sh/ch)
 elif mode=='colsfirst': cols=rf(sw/cw);rows=rf(cols*fr/(w/h))
 elif mode=='rowsfirst': rows=rf(sh/ch);cols=rf(rows*(w/h)/fr)
 elif mode=='fitceilbox': cols,rows=calcfit(w,h,ceil(sw/cw),ceil(sh/ch),fr,True,roundmode)
 elif mode=='fitboxsrc': cols,rows=calcfit(w,h,ceil(sw/cw),ceil(sh/ch),fr,False,roundmode)
 # apply view cap 80x24 via fit
 if cols>80 or rows>24:
  cols,rows=calcfit(w,h,80,24,fr,True,'ceil')
 return cols,rows
best=[]
for cellmode in ['short10','term','area200','height20','width10']:
 for mode in ['indep','colsfirst','rowsfirst','fitceilbox','fitboxsrc']:
  for rm in ['ceil','round','floor']:
   score=sum(1 for w,h,fr,scale,d in data if predict(w,h,fr,scale,cellmode,mode,rm)==d)
   best.append((score,cellmode,mode,rm))
best.sort(reverse=True)
for b in best[:20]:print(b,'/',len(data))
PY
python3 /tmp/fitgeom2.py"}

