old='''	counts := map[RGBA]int{}
	for i, c := range comp {
		if op[i] {
			counts[c]++
		}
	}'''
new='''	// The reference quantiser first reduces colours to 4 bits per channel.
	type bucketKey struct{ r, g, b int }
	type bucketAcc struct{ sr, sg, sb, n int }
	buckets := map[bucketKey]*bucketAcc{}
	for i, c := range comp {
		if op[i] {
			k := bucketKey{int(c.R) >> 4, int(c.G) >> 4, int(c.B) >> 4}
			acc := buckets[k]
			if acc == nil {
				acc = &bucketAcc{}
				buckets[k] = acc
			}
			acc.sr += int(c.R)
			acc.sg += int(c.G)
			acc.sb += int(c.B)
			acc.n++
		}
	}
	counts := map[RGBA]int{}
	for _, acc := range buckets {
		c := RGBA{uint8((acc.sr + acc.n/2) / acc.n), uint8((acc.sg + acc.n/2) / acc.n), uint8((acc.sb + acc.n/2) / acc.n), 255}
		counts[c] += acc.n
	}'''
assert old in s
s=s.replace(old,new)
