import subprocess,sys,re,os,json,zlib,struct,concurrent.futures
def pngbytes(pixels,w,h):
    raw=b''
    for row in pixels: raw+=b'\x00'+b''.join(bytes(p) for p in row)
    def chunk(t,data): return struct.pack(">I",len(data))+t+data+struct.pack(">I",zlib.crc32(t+data)&0xffffffff)
    return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack(">IIBBBBB",w,h,8,2,0,0,0))+chunk(b'IDAT',zlib.compress(raw))+chunk(b'IEND',b'')
def run_one(task):
    cp,x,y=task
    pix=[[(255,255,255) if (xx==x and yy==y) else (0,0,0) for xx in range(16)] for yy in range(8)]
    env={"PATH":os.environ.get("PATH",""),"LC_ALL":"C.UTF-8"}
    p=subprocess.run(["./orig_executable","--probe=off","-f","symbols","-c","full","-s","2x1","--stretch","-p","off",f"--symbols=U+{cp:04X}","-"],input=pngbytes(pix,16,8),capture_output=True,env=env,timeout=5)
    out=p.stdout
    fg=re.search(br'38;2;(\d+);(\d+);(\d+)',out); bg=re.search(br'48;2;(\d+);(\d+);(\d+)',out)
    f=int(fg.group(1)) if fg else 0; b=int(bg.group(1)) if bg else 0
    txt=re.sub(br'\x1b\[[0-9;]*m',b'',out).decode('utf-8','replace').strip('\n')
    return (cp,x,y,f,b,txt)
