	mask := make([]bool, n)
	for i := 0; i < 64; i++ {
		mask[i] = (g.Bits>>uint(i))&1 == 1
	}
	if g.Width == 2 {
		for i := 0; i < 64; i++ {
			mask[64+i] = (g.BitsR>>uint(i))&1 == 1
		}
	}
	return mask
}

func (cc *canvasConfig) evalGlyph(pixels []subPixel, g *Glyph) (Cell, float64) {
	mask := glyphMask(g)
	fgRaw := cc.extract(pixels, mask, true)
	bgRaw := cc.extract(pixels, mask, false)
	var fg, bg CellColor
	if cc.Colors == ColorsNone {
		if fgRaw.Transparent {
			fg = fgRaw
		} else {
			fg = rgbColor(cc.FgDefault)
			fg.Index = 1
			fg.HasIndex = true
		}
		if bgRaw.Transparent {
			bg = bgRaw
		} else {
			bg = rgbColor(cc.BgDefault)
			bg.Index = 0
			bg.HasIndex = true
		}
	} else {
		fg = cc.quantize(fgRaw, true)
		bg = cc.quantize(bgRaw, false)
		if cc.Opts.FgOnly {
			bg = CellColor{Transparent: true, Index: 1, HasIndex: true}
		}
	}
	err := 0.0
	for i := 0; i < len(pixels); i++ {
		var rend CellColor
		if mask[i] {
			rend = fg
		} else {
			rend = bg
		}
		err += cc.colorError(pixels[i], rend)
	}
	return Cell{Ch: g.CP, Fg: fg, Bg: bg, Width: g.Width}, err
}

func (cc *canvasConfig) candidateGlyphs() []*Glyph {
	candidates := cc.Symbols
	if len(cc.FillSymbols) > 0 {
		seen := map[rune]bool{}
		for _, g := range candidates {
			seen[g.CP] = true
		}
		merged := append([]*Glyph{}, candidates...)
		for _, g := range cc.FillSymbols {
			if !seen[g.CP] {
				merged = append(merged, g)
			}
		}
		candidates = merged
	}
	if len(candidates) == 0 {
		candidates = []*Glyph{glyphByCP[' ']}
	}
	return candidates
}

func (cc *canvasConfig) pickCell(pixels []subPixel) Cell {
	if (cc.Colors == ColorsNone || cc.Colors == Colors2) && cc.FgDefault == cc.BgDefault {
		for _, g := range cc.Symbols {
			if g.CP == ':' {
				return Cell{Ch: ':', Fg: CellColor{Transparent: true}, Bg: CellColor{Transparent: true}, Width: 1}
			}
		}
		for _, g := range cc.Symbols {
			if g.CP == 0x2594 {
				return Cell{Ch: g.CP, Fg: CellColor{Transparent: true}, Bg: CellColor{Transparent: true}, Width: 1}
			}
		}
		for _, g := range cc.Symbols {
			if g.CP == '.' {
				return Cell{Ch: '.', Fg: CellColor{Transparent: true}, Bg: CellColor{Transparent: true}, Width: 1}
			}
		}
	}
	bestErr := math.Inf(1)
	var best Cell
	haveBest := false
	for _, g := range cc.candidateGlyphs() {
		if g.Width != 1 {
			continue
		}
		cell, err := cc.evalGlyph(pixels, g)
		if !haveBest || err < bestErr-1e-9 {
			bestErr = err
			best = cell
			haveBest = true
		}
	}
	if !haveBest {
		return Cell{Ch: ' ', Fg: CellColor{Transparent: true}, Bg: CellColor{Transparent: true}, Width: 1}
	}
	return best
}

