func (cc *canvasConfig) evalGlyph(pixels []subPixel, g *Glyph) (Cell, float64) {
	mask := glyphMask(g)
	fgRaw := cc.extract(pixels, mask, true)
	bgRaw := cc.extract(pixels, mask, false)
