var coarseModeCache = -1

func coarseMode() string {
	return getenvCoarse()
}

func (cc *canvasConfig) evalGlyphCoarse(pixels []subPixel, g *Glyph) (Cell, float64) {
	mode := coarseMode()
	grid := 4
	if cc.Opts.Work <= 2 {
		grid = 2
	}
	block := 8 / grid
	// Build sample colours (block averages in premultiplied space) and sample mask bits.
	type sample struct {
		col [4]float64
		bit bool
	}
	samples := make([]sample, 0, grid*grid)
	maskFull := glyphMask(g)
	for by := 0; by < grid; by++ {
		for bx := 0; bx < grid; bx++ {
			var acc [4]float64
			cover := 0
			n := 0
			for y := by * block; y < (by+1)*block; y++ {
				for x := bx * block; x < (bx+1)*block; x++ {
					i := y*8 + x
					p := pixels[i]
					if !p.transparent {
						acc[0] += float64(p.col.R)
						acc[1] += float64(p.col.G)
						acc[2] += float64(p.col.B)
						acc[3] += 255
					}
					if maskFull[i] {
						cover++
					}
					n++
				}
			}
			for k := 0; k < 4; k++ {
				acc[k] /= float64(n)
			}
			var bit bool
			switch mode {
			case "maj2":
				bit = cover*2 >= n
			case "maj3":
				bit = cover*2 > n
			case "center":
				cx := bx*block + block/2
				cy := by*block + block/2
				bit = maskFull[cy*8+cx]
			default: // "cov"
				bit = cover > 0
			}
			if mode == "cov" {
				// handled below via fraction; store cover in a parallel slice by encoding in col alpha? use samples with bit and a separate frac slice
			}
			samples = append(samples, sample{acc, bit})
			_ = cover
		}
	}
	// Extract fg/bg from full mask as usual
	fgRaw := cc.extract(pixels, maskFull, true)
	bgRaw := cc.extract(pixels, maskFull, false)
	var fg, bg CellColor
	if cc.Colors == ColorsNone {
		if fgRaw.Transparent {
			fg = fgRaw
		} else {
			fg = rgbColor(cc.FgDefault)
			fg.Index = 1
			fg.HasIndex = true
		}
		if bgRaw.Transparent {
			bg = bgRaw
		} else {
			bg = rgbColor(cc.BgDefault)
			bg.Index = 0
			bg.HasIndex = true
		}
		// Scalar intensity scoring on samples
		fgI := (float64(cc.FgDefault.R) + float64(cc.FgDefault.G) + float64(cc.FgDefault.B)) / 3
		bgI := (float64(cc.BgDefault.R) + float64(cc.BgDefault.G) + float64(cc.BgDefault.B)) / 3
		if cc.FgDefault == (RGBA{255, 255, 255, 255}) && cc.BgDefault == (RGBA{0, 0, 0, 255}) {
			if cc.Opts.Work >= 3 {
				fgI = 170
			} else {
				fgI = 255
			}
		}
		err := 0.0
		for _, sm := range samples {
			var ip float64
			if sm.col[3] == 0 {
				ip = bgI
			} else {
				ip = (sm.col[0] + sm.col[1] + sm.col[2]) / 3 * (255 / sm.col[3])
				// acc RGB are premultiplied sums averaged with alpha in [0,255]; unpremultiply approx:
				// Actually acc[0..2] already are averages of composited colours (alpha 255 for opaque), so the factor above double-counts for semi-transparent; keep simple:
				ip = (sm.col[0] + sm.col[1] + sm.col[2]) / 3
