	if cc.Opts.FgOnly {
		bg = CellColor{Transparent: true, Index: 1, HasIndex: true}
	}
	premult := func(c CellColor) [4]float64 {
		if c.Transparent {
			return [4]float64{0, 0, 0, 0}
		}
