{"command":"cat > glibprint.go << 'EOF'
package main

import (
	"fmt"
	"os"
	"unicode/utf8"
)

// glibStderr writes a message to stderr mimicking GLib's g_printerr
// conversion from UTF-8 to the locale charset.
func glibStderr(s string) {
	if localeIsUTF8() {
		_, _ = os.Stderr.WriteString(s)
		return
	}
	if utf8.ValidString(s) {
		out := make([]rune, 0, len(s))
		for _, r := range s {
			if r > 127 {
				out = append(out, '?')
			} else {
				out = append(out, r)
			}
		}
		_, _ = os.Stderr.WriteString(string(out))
		return
	}
	// Invalid UTF-8: escape every non-ASCII byte as \xXX.
	buf := make([]byte, 0, len(s)+16)
	buf = append(buf, "[Invalid UTF-8] "...)
	const hexd = "0123456789abcdef"
	for i := 0; i < len(s); i++ {
		b := s[i]
		if b >= 0x80 {
			buf = append(buf, '\\', 'x', hexd[b>>4], hexd[b&0xf])
		} else {
			buf = append(buf, b)
		}
	}
	_, _ = os.Stderr.Write(buf)
}

func glibErrorf(format string, args ...interface{}) {
	glibStderr(fmt.Sprintf(format, args...))
}
